COLLDATA("seeratency","ur",[[921,"[تصویر: سلامتی کا گھر (مسجد الحرام)]\n3 ’’میں اس مکان میں سلامتی بخشوں گا‘‘: قرآن مجید میں بھی خانہ کعبہ کی سب سے بڑی صفت یہاں کا امن بیان کی گئی ہے:\n﴿وَإِذْ جَعَلْنَا الْبَيْتَ مَثَابَةً لِّلنَّاسِ وَأَمْنًا وَّاتَّخِذُوْا مِنْ مَّقَامِ إِبْرٰهِمَ مُصَلًّى﴾\n’’اور جب ہم نے بیت اللہ کو لوگوں کے لیے بار بار لوٹ کر آنے کی اور امن کی جگہ بنایا اور (حکم دیا کہ) تم مقام ابراہیم کو جائے نماز بناؤ۔‘‘(1)\nعوفی نے سیدنا ابن عباس رضی اللہ عنہ سے اس آیت کریمہ کی تفسیر میں روایت کیا ہے کہ اس کے معنی یہ ہیں: لوگ اس گھر میں آئیں گے لیکن ان کا دل نہیں بھرے گا، چنانچہ وہ اپنے گھروں کو واپس جائیں گے تو دوبارہ سہ بارہ آئیں گے۔(2)","",{"v":200442,"fn":"(1) البقرة 2:125۔\n(2) تفسير الطبري، البقرة 2:125۔","im":["v2_p442.jpg"]}],[922,"[تصویر: مسجد الحرام میں حجاج کا اجتماع]\n﴿مَثَابَةً لِّلنَّاسِ﴾ کے معنی ہیں لوگوں کے جمع ہونے کی جگہ، یعنی اسے ایک ایسا مقام بنا دیا ہے کہ روحیں اس کے لیے اس قدر مشتاق اور بے قرار رہتی ہیں کہ وہ اس سے کبھی سیر ہی نہیں ہوتیں، چاہے ہر سال یہاں حاضری دیں کیونکہ اللہ تعالیٰ نے بیت اللہ کے بارے میں اپنے خلیل کی اس دعا کو بھی شرف قبولیت سے نواز دیا تھا کہ ﴿فَاجْعَلْ أَفْئِدَةً مِّنَ النَّاسِ تَهْوِيْ إِلَيْهِمْ﴾(1) ’’پس تو بعض لوگوں کے دلوں کو ایسا کر دے کہ ان کی طرف جھکے رہیں۔‘‘ نیز اللہ تعالیٰ نے بیت اللہ کو اس قدر امن اور سکون کا گہوارہ بنا دیا کہ جو اس میں داخل ہو جائے، وہ آغوش امن میں آ جاتا ہے، چاہے وہ کتنا ہی بڑا جرم کر کے آیا ہو، اُسے بیت اللہ کی حدود میں کوئی کچھ نہیں کہہ سکتا۔ یہی معنی ہیں صحیفۂ حبقوق کی اس پیش گوئی کے کہ ’’میں اس مکان میں سلامتی بخشوں گا۔‘‘","",{"v":200443,"fn":"(1) إبراهيم 14:37۔","im":["v2_p443.jpg"]}],[923,"خاتم النبیین صلی اللہ علیہ وسلم کی بعثت و صداقت قرآن مجید میں اللہ تعالیٰ نے فرمایا:\n﴿وَمُبَشِّرًا بِرَسُوْلٍ يَّأْتِيْ مِنْ بَعْدِي اسْمُهُ أَحْمَدُ﴾\n’’اور ایک رسول کی بشارت دینے والا ہوں، وہ میرے بعد آئے گا، اس کا نام احمد ہوگا۔‘‘ (الصف 61:6)","",{"v":200444}],[924,"خاتم النبیین صلی اللہ علیہ وسلم کی بعثت و صداقت قرآن کی مذکورہ آیت کی صداقت بائبل سے ہوتی ہے:\nلَا أَتَكَلَّمُ أَيْضًا مَعَكُمْ كَثِيْرًا، لِأَنَّ رَئِيْسَ هٰذَا الْعَالَمِ يَأْتِيْ وَلَيْسَ لَهُ فِيَّ شَيْءٌ۔\n’’(عیسیٰ علیہ السلام نے کہا) اس کے بعد میں تم سے بہت سی باتیں نہ کروں گا کیونکہ دنیا کا سردار آتا ہے اور مجھ میں اس کا کچھ نہیں۔‘‘ کتاب مقدس (یوحنا) 14:30\nوَأَمَّا الْمُعَزِّيْ، الرُّوْحُ الْقُدُسُ، الَّذِيْ سَيُرْسِلُهُ الْآبُ بِاسْمِيْ، فَهُوَ يُعَلِّمُكُمْ كُلَّ شَيْءٍ، وَيُذَكِّرُكُمْ بِكُلِّ مَا قُلْتُهُ لَكُمْ۔\n’’لیکن مددگار یعنی روح القدس جسے باپ میرے نام سے بھیجے گا وہی تمھیں سب باتیں سکھائے گا اور جو کچھ میں نے تم سے کہا ہے وہ سب تمھیں یاد دلائے گا۔‘‘ کتاب مقدس (یوحنا) 14:26\nلٰكِنِّيْ أَقُوْلُ لَكُمُ الْحَقَّ: إِنَّهُ خَيْرٌ لَكُمْ أَنْ أَنْطَلِقَ، لِأَنَّهُ إِنْ لَمْ أَنْطَلِقْ لَا يَأْتِيْكُمُ الْمُعَزِّيْ۔ وَلٰكِنْ إِنْ ذَهَبْتُ أُرْسِلُهُ إِلَيْكُمْ۔\n’’لیکن میں تم سے سچ کہتا ہوں کہ میرا جانا تمھارے لیے فائدہ مند ہے کیونکہ اگر میں نہ جاؤں تو وہ مددگار تمھارے پاس نہ آئے گا لیکن اگر جاؤں گا تو اُسے تمھارے پاس بھیج دوں گا۔‘‘ کتاب مقدس (یوحنا) 16:7","",{"v":200445}],[925,"§صحیفۂ ملاکی کی بشارت\nاللہ تعالیٰ نے صحف مقدسہ میں خاتم النبیین صلی اللہ علیہ وسلم کے لیے جو نام استعمال کیے ہیں، ان میں سے ایک ایلیاہ بھی ہے جس کے اعداد یہودی حساب سے 53 بنتے ہیں اور ’’احمد‘‘ کے اعداد اس کے مساوی ہیں۔(1)\n§الیاس اور ایلیاہ\nایلیاہ نام کے ایک عظیم نبی جنھیں اللہ تعالیٰ نے بنی اسرائیل کی طرف بھیجا تھا، ان کا عہد نویں صدی ق م تھا۔ قرآن میں انھیں ’’الیاس‘‘ کہا گیا ہے:\n﴿وَإِنَّ إِلْيَاسَ لَمِنَ الْمُرْسَلِيْنَ﴾ ’’اور بلاشبہ الیاس یقیناً رسولوں میں سے تھا۔‘‘(2)\nایک ’’ایلیاہ‘‘ یا ملاکی ان کے سات سو سال بعد مبعوث ہوئے(3) جنھوں نے اپنے مختصر صحیفے میں بنی اسرائیل کو ان کی سرکشی کے خطرناک نتائج سے آگاہ کیا۔(4)\n[تصویر: اردن کے قصبہ تشبہ کا ایک منظر]\nایلیاہ (Elijah بمعنی اللہ میرا معبود ہے) جلعاد (اردن) کے قصبہ تشبہ (Tishbe) کے رہنے والے تھے۔ انھیں بعل نامی بُت کے پجاریوں کی ہدایت کے لیے بھیجا گیا۔ یہود کی شمالی ریاست اسرائیل کا شاہ احاب یا اخی اب (874 تا 853 ق م) کھلم کھلا بعل کی پوجا کو فروغ دینے لگا تھا، لہٰذا اللہ تعالیٰ نے موسیٰ علیہ السلام کی طرح الیاس علیہ السلام کو","",{"v":200446,"fn":"(1) ایلیاہ (ا = 1، ی = 10، ل = 30، ی = 10، ا = 1، ا = 1) = 53، احمد (ا = 1، ح = 8، م = 40، د = 4) = 53۔\n(2) الصافات 37:123۔\n(3) ملاکی: کتاب مقدس (بائبل) میں ملاکی نبی کی کتاب کا زمانہ پانچویں صدی قبل مسیح بتایا گیا ہے جب یروشلیم میں ہیکل دوبارہ تعمیر ہو چکا تھا (کتاب مقدس، ص: 1145) یعنی ملاکی، الیاس علیہ السلام کے چار سو سال بعد مبعوث ہوئے۔\n(4) هل بشر الكتاب المقدس بمحمد صلی اللہ علیہ وسلم؟، ص: 115۔","im":["v2_p446.jpg"]}],[926,"مبعوث فرمایا۔ کوہ کرمل پر الیاس علیہ السلام کی طرف سے بیل کی سوختنی قربانی قبول ہونے کا معجزہ دکھانے پر لوگ بعل کی پوجا کرنے سے باز آگئے اور بعل کے 450 پروہت قتل کر دیے گئے۔ ایلیاہ کی دعا سے خشک سالی دور ہوئی۔ شاہ احاب کی بت پرست ملکہ ایزبل کو بعل کے پروہتوں کے قتل کا علم ہوا۔ نتیجتاً اس نے ایلیاہ (علیہ السلام) کو قتل کرنے کی دھمکی دی۔ اس صورت حال میں وہ پہلے بئر سبع گئے اور پھر حورب (سینا) کے غار میں جا چھپے۔\n[تصویر: جزیرہ نمائے سینا میں وادی موسیٰ اور فرش ایلیاہ]\nخدا نے انھیں دمشق کے بیابان جانے کی ہدایت کی۔ راستے میں انھوں نے الیشع بن سافط (الیسع علیہ السلام) کو مسح کیا اور وہ ان کی جگہ نبی ہوئے۔ ایلیاہ الیشع کے ہمراہ بیت ایل (بیت المقدس) اور اریحا سے ہوتے ہوئے دریائے یردن (اردن) کے کنارے پر پہنچ گئے۔ ایلیاہ نے اپنی چادر لپیٹ کر پانی پر ماری تو وہ دو حصے ہو گیا اور وہ دریا پار کر گئے۔ پھر خداوند نے ایلیاہ کو بگولے میں آسمان پر اٹھا لیا۔(1) یوحنا بپتسمہ دینے والے (یحییٰ علیہ السلام) کو بھی ایلیاہ کہا گیا ہے۔(2) الیاس علیہ السلام اسرائیلی نبی تھے جو الیسع علیہ السلام کے چچازاد بھائی تھے۔ قرآن میں ان کا نام الیاسین بھی آیا ہے۔(3)\nصحیفۂ ملاکی میں لکھا ہے:\n’’دیکھو میں اپنے رسول کو بھیجوں گا اور وہ میرے آگے راہ درست کرے گا اور خداوند جس کے تم طالب","",{"v":200447,"fn":"(1) کتاب مقدس (1-سلاطین) 17,18,19 اور 2-سلاطین باب 2۔\n(2) NIV Study Bible, p: 509؛ کتاب مقدس (متی) 11:14۔\n(3) الصافات 37:130۔","im":["v2_p447.jpg"]}],[927,"ہو ناگہاں اپنی ہیکل میں آ موجود ہوگا۔ ہاں عہد کا رسول جس کے تم آرزو مند ہو آئے گا رب الافواج فرماتا ہے۔ پر اُس کے آنے کے دن کی کس میں تاب ہے؟ اور جب اُس کا ظہور ہوگا تو کون کھڑا رہ سکے گا؟ کیونکہ وہ سنار کی آگ اور دھوبی کے صابون کی مانند ہے۔‘‘(1)\n[تصویر: صحیفۂ ’’ملاکی‘‘ کا ایک ورق]\n1 ’’جس کے تم طالب ہو ناگہاں اپنی ہیکل میں آ موجود ہوگا‘‘: ملاکی عہد نامہ قدیم کی آخری کتاب ہے۔ بائبل کے شارحین کہتے ہیں کہ اس پیش گوئی میں دو نبیوں کا ذکر ہوا ہے۔ ایک یوحنا (یحییٰ علیہ السلام) اور دوسرے عیسیٰ (علیہ السلام) ہیں۔(2) ہیکل کے لغوی معانی میں ’’بڑی عمارت، بت خانہ، یہودیوں کا بڑا مقدس معبد یا کلیسائی قربان گاہ‘‘ شامل ہیں۔(3) یروشلیم میں کوہ موریاہ پر یکے بعد دیگرے تین ہیکلیں تعمیر ہوئیں۔ آج کل اس جگہ کو حرم الشریف کہتے ہیں (جہاں مسجد اقصیٰ اور قبۃ الصخرہ واقع ہیں)۔ پہلی ہیکل سلیمان بادشاہ (علیہ السلام) نے تعمیر کی تھی۔ دوسری زربابل اور ان یہودیوں نے تعمیر کی جو بابل کی اسیری سے واپس آئے تھے۔ تیسری ہیکل جو مسیح (علیہ السلام) کے زمانے میں موجود تھی، اسے ہیرودیس بادشاہ نے تعمیر کرایا تھا۔ مجدو اور حصور میں جو کنعانی مندر ملے ہیں، وہ نقشے کے لحاظ سے عبرانی ہیکل سے بڑی حد تک ملتے جلتے تھے لیکن یروشلیم کی ہیکل اس لحاظ سے منفرد تھی کہ اس کے اندرونی عبادت خانہ میں بت نہیں تھے بلکہ ایک صندوق (جسے عہد کا صندوق کہتے تھے) رکھا ہوا تھا جس میں شریعت کی دو تختیاں تھیں اور صندوق کے سرپوش پر سونے سے گھڑے ہوئے بحالت پرستش دو فرشتے تھے۔(4)\nنوٹ: زربابل (زروب بابل: بابل کی شاخ یا بیج، یعنی بابل میں پیدا ہوا): جب شاہ فارس خورس (سائرس یا ذوالقرنین) نے یہودیوں کو (538 ق م میں) وطن واپس جانے کی اجازت دی تو زربابل کو یہوداہ (ریاست یہودیہ) کا ناظم مقرر کیا۔ یروشلیم پہنچنے پر زربابل نے سوختنی قربانی کا مذبح بنایا اور ہیکل کی بنیاد ڈالی مگر یہودیوں نے شاہ فارس سے شکایت کر کے کام رکوا دیا۔ 520 ق م میں یہ کام پھر شروع ہوا اور چار سال میں","",{"v":200448,"fn":"(1) کتاب مقدس (ملاکی) 3:1,2۔\n(2) Life Application Study Bible, P: 1389۔\n(3) المعجم الوسيط، مادة: هيكل۔\n(4) قاموس الكتاب، ص: 1091۔","im":["v2_p448.jpg"]}],[928,"[تصویر: مسجد الاقصی اور قبۃ الصخرہ جہاں یکے بعد دیگرے 3 ہیکلیں تعمیر ہوئیں]\nمکمل کیا گیا۔\nبائبل کے شارحین کی باتوں میں عجیب تضاد ہے۔ ایک طرف وہ یسوع کو خدا کا بیٹا، خدا اور اقانیم ثلاثہ میں سے ایک اقنوم قرار دیتے ہیں اور دوسری طرف بائبل میں جہاں کہیں انبیاء اور رسولوں کے متعلق پیش گوئیاں نظر آتی ہیں، انھیں بھی یسوع پر چسپاں کرنے کی کوشش کرتے ہیں۔ ’’جس کے تم طالب ہو ناگہاں اپنی ہیکل میں آموجود ہوگا‘‘ اس پیش گوئی میں واضح طور پر موجود ہے کہ ’’جب اُس کا ظہور ہوگا تو کون کھڑا رہ سکے گا؟‘‘ یسوع اور یوحنا دونوں میں سے کسی نے نہ تو ہیکل پر غلبہ پایا، نہ انھیں ایسی پوزیشن ملی کہ اُن کے سامنے کوئی کھڑا نہ ہو سکے۔ یوں عیسیٰ اور یحییٰ علیہما السلام اس پیش گوئی کے مصداق نہیں بنتے، لامحالہ اس سے نبی کریم صلی اللہ علیہ وسلم ہی مراد ہیں۔ جب آپ نے مکہ فتح کیا تو گویا اپنی ہیکل (کعبہ) کو واگزار کرایا۔ یاد رہے پیش گوئی میں ہیکل سلیمانی کا ذکر نہیں بلکہ ’’اپنی ہیکل‘‘ کے الفاظ مذکور ہیں۔ اس ظہور (فتح مکہ) کے وقت سب کی گردنیں آپ کے سامنے جھکی ہوئی تھیں۔ کسی میں جرات نہیں تھی کہ نبی کریم صلی اللہ علیہ وسلم کے سامنے کھڑا ہو سکے۔\nنبی صلی اللہ علیہ وسلم نے ان سے فرمایا تھا: ’’تم مجھ سے کیسے سلوک کی توقع رکھتے ہو؟‘‘ جواباً ان جھکی گردنوں والوں نے کہا تھا: ’’بھلائی کی! آپ ہمارے کریم بھائی اور کریم بھائی کے بیٹے ہیں۔‘‘ اس پر آپ صلی اللہ علیہ وسلم نے فرمایا تھا:\n﴿اذْهَبُوا فَأَنْتُمُ الطُّلَقَاءُ﴾\n’’جاؤ! تم سب آزاد ہو۔‘‘\nایک اور روایت میں ہے کہ آپ صلی اللہ علیہ وسلم نے فرمایا:\n﴿أَقُولُ كَمَا قَالَ يُوسُفُ: لَا تَثْرِيبَ عَلَيْكُمُ الْيَوْمَ يَغْفِرُ اللَّهُ لَكُمْ وَهُوَ أَرْحَمُ الرَّاحِمِينَ﴾ (یوسف 12:92)\n۱ قاموس الکتاب، ص: 477,478","",{"v":200449,"im":["v2_p449.jpg"]}],[929,"’’میں وہی کہتا ہوں جو یوسف علیہ السلام نے کہا تھا: ’تم پر آج کوئی ملامت نہیں، اللہ تمھاری مغفرت کرے اور وہ ارحم الراحمین ہے۔‘(1)\n2 سنار کی آگ اور دھوبی کے صابون کی مانند: مذکورہ پیش گوئی میں ’’سنار کی آگ‘‘ اور ’’دھوبی کے صابون‘‘ کے الفاظ بھی نبی کریم صلی اللہ علیہ وسلم ہی کی طرف اشارہ کرتے ہیں کیونکہ آپ نے تمام کھرا اور کھوٹا الگ کر دکھایا، باطل کے اندھیرے چھٹ گئے اور حق روشن ہو کر دنیا کے سامنے آگیا۔ اللہ تعالیٰ نے فرمایا:\n﴿قُلْ جَاءَ الْحَقُّ وَزَهَقَ الْبَاطِلُ ۚ إِنَّ الْبَاطِلَ كَانَ زَهُوقًا﴾\n’’اور (اے نبی!) کہہ دیجیے کہ حق آگیا اور باطل مٹ گیا۔ بے شک باطل تو مٹنے ہی والا ہے۔‘‘(2)\n﴿قُلْ جَاءَ الْحَقُّ وَمَا يُبْدِئُ الْبَاطِلُ وَمَا يُعِيدُ﴾\n’’آپ کہہ دیجیے: حق آگیا اور باطل نہ پہلی بار ابھرا (نہ دوبارہ ابھرے گا)۔‘‘(3)\nسیدنا عرباض بن ساریہ رضی اللہ عنہ سے مروی حدیث میں رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n﴿قَدْ تَرَكْتُكُمْ عَلَى الْبَيْضَاءِ، لَيْلُهَا كَنَهَارِهَا، لَا يَزِيغُ عَنْهَا بَعْدِي إِلَّا هَالِكٌ﴾\n’’یقیناً میں تمھیں روشن (شریعت) پر چھوڑ رہا ہوں۔ اس کی رات بھی دن کی طرح (روشن) ہے۔ میرے بعد اس سے صرف وہی کج روی اختیار کرے گا جو ہلاک ہونے والا ہے۔‘‘(4)\n3 ’’سردار‘‘ اور ’’عہد کا رسول‘‘: ڈاکٹر منقذ محمود السقار لکھتے ہیں: ملاکی نبی کے صحیفے (ملاکی 3:1,2) میں دو آدمیوں کے بارے میں پیش گوئی کی گئی ہے۔ ان میں سے ایک وہ ہے جو رب کی طرف سے آنے والے کے لیے راہ درست کرے گا۔ دوسرا وہ ہے جو ’’ناگہاں اپنی ہیکل میں آموجود ہوگا‘‘(5) اور اس صحیفے میں اس کے لیے ’’سردار‘‘ اور ’’عہد کا رسول‘‘ کے القاب استعمال ہوئے ہیں۔ بنی اسرائیل اسی کی آمد کے متمنی اور منتظر تھے۔\nملاکی نبی اپنے صحیفے کے آخر میں اس آنے والے کے متعلق کہتے ہیں: ‘‘تم میرے بندہ موسیٰ کی شریعت، یعنی ان فرائض و احکام کو، جو میں نے حورب پر تمام بنی اسرائیل کے لیے فرمائے یاد رکھو۔ دیکھو خداوند کے بزرگ اور","",{"v":200450,"fn":"(1) السنن الکبریٰ للبیہقی: 118/9، السنن الکبریٰ للنسائی: 382,383/6\n(2) بنی إسرآءیل 17:81\n(3) سبا 34:49\n(4) سنن ابن ماجہ: 43\n(5) عربی بائبل \"الکتاب المقدس\" میں لقب السید (سردار) اور انگریزی بائبل (NIV Study Bible) میں لفظ Lord موجود ہے جسے اردو بائبل (کتاب مقدس) میں حذف کر دیا گیا ہے۔"}],[930,"ہولناک دن کے آنے سے پیشتر میں ایلیاہ نبی کو تمھارے پاس بھیجوں گا۔ اور وہ باپ کا دل بیٹے کی طرف اور بیٹے کا باپ کی طرف مائل کرے گا۔ مبادا میں آؤں اور زمین کو ملعون کروں۔‘‘(1)\n§موسیٰ علیہ السلام کی وصیت\nملاکی نبی نے یہاں کوہ حوریب (حورب) پر بنی اسرائیل کے سامنے موسیٰ علیہ السلام کی وصیت کا تذکرہ کیا ہے جس میں موسیٰ علیہ السلام نے اپنے جیسے آنے والے ایک نبی کا ذکر کیا جو بنی اسرائیل کے بھائیوں (بنی اسماعیل) میں سے ہوگا۔ ملاکی نبی نے اس آنے والے نبی کا نام ایلیاء (ایلیاہ) بتایا۔ تحفۃ الانجیل کے مصنف نے اس کی وضاحت کرتے ہوئے لکھا ہے: ’’صحیفہ ملاکی کے آخری حصے میں مذکور ایلیاہ نبی کا کردار ایک معما ہے اور وہ دنیا کا سب سے بڑا عالم ہے جو آخری زمانے میں آنے والا ہے۔‘‘\nعیسائیوں کے خیال میں وہ پیغمبر جس نے آنے والے کے لیے راستہ ہموار کیا، وہ یوحنا اصطباغی موسوم بہ ایلیاہ ہے جیسا کہ انجیل مرقس میں لکھا ہے: ‘‘دیکھ میں اپنا پیغمبر تیرے آگے بھیجتا ہوں جو تیری راہ تیار کرے گا۔ بیابان میں پکارنے والے کی آواز آتی ہے کہ خداوند کی راہ تیار کرو۔ اس کے راستے سیدھے بناؤ۔ یوحنا آیا اور بیابان میں بپتسمہ دیتا اور گناہوں کی معافی کے لیے توبہ کے بپتسمہ کی منادی کرتا تھا۔ اور یہودیہ کے ملک کے سب لوگ اور یروشلم کے سب رہنے والے نکل کر اس کے پاس گئے اور انھوں نے اپنے گناہوں کا اقرار کر کے دریائے یردن\n[تصویر: بائبل کے مطابق دریائے اردن پر وہ جگہ جہاں یوحنا نے لوگوں کو بپتسمہ دیا]","",{"v":200451,"fn":"(1) کتاب مقدس (ملاکی) 4:4-6","im":["v2_p451.jpg"]}],[931,"میں اس سے بپتسمہ لیا۔ اور یوحنا اونٹ کے بالوں کا لباس پہنے اور چمڑے کا پٹکا اپنی کمر سے باندھے رہتا اور ٹڈیاں اور جنگلی شہد کھاتا تھا۔ اور منادی کرتا تھا کہ میرے بعد وہ شخص آنے والا ہے جو مجھ سے زور آور ہے۔ میں اس لائق نہیں کہ جھک کر اس کی جوتیوں کا تسمہ کھولوں۔ میں نے تو تم کو پانی سے بپتسمہ دیا مگر وہ تم کو روح القدس سے بپتسمہ دے گا۔‘‘(1)\nایسی ہی بات انجیل لوقا میں مسیح (علیہ السلام) کی زبانی نقل کی گئی ہے: ’’تو پھر تم کیا دیکھنے گئے تھے؟ کیا ایک نبی؟ ہاں میں تم سے کہتا ہوں بلکہ نبی سے بڑے (رسول) کو۔ یہ وہی ہے جس کی بابت لکھا ہے کہ دیکھ میں اپنا پیغمبر تیرے آگے بھیجتا ہوں جو تیری راہ تیرے آگے تیار کرے گا۔‘‘(2)\nعیسائیوں کے خیال میں راستہ ہموار کرنے والا یوحنا اصطباغی ہے اور جس کے لیے راستہ ہموار کیا گیا ہے، وہ یسوع مسیح (عیسیٰ علیہ السلام) ہیں اور یہ لوگ (نصاریٰ) یوحنا کو ایلیاہ کے نام سے یاد کرتے ہیں جیسے کہ متی نے بھی مسیح (علیہ السلام) کی زبان سے یوحنا اصطباغی کے بارے میں بیان کیا ہے۔(3)\n’’ختنے والا پیغمبر‘‘\nصحیح بات یہ ہے کہ ایلیاہ آنے والے نبی کی طرف اشارہ ہے اور اس سے مراد راستہ ہموار کرنے والا نبی نہیں۔ ڈاکٹر السقار لکھتے ہیں: ‘‘اس سے پہلے کہ ہم اس آنے والے نبی کا تعین کریں، ہم یہ واضح کر دینا چاہتے ہیں کہ موجودہ بائبل کے متن میں بے تحاشا تحریف ہو چکی ہے جیسے صحیفہ ملاکی میں آنے والے نبی کو ‘‘عہد کا رسول‘‘ کہا گیا ہے جبکہ بائبل کے پرانے ترجموں میں اسے ‘‘ختنے والا پیغمبر‘‘ قرار دیا گیا ہے۔ بائبل کے جدید ترجمے میں عبارت ہے ‘‘ملاکی نے بھیجا‘‘ جبکہ پرانے نسخے میں یہ الفاظ آئے ہیں: ‘‘میں اپنا رسول بھیجوں گا‘‘۔ بعض نسخوں میں ‘‘سردار آئے گا‘‘ کے الفاظ رقم ہوئے ہیں جبکہ بعض میں اسے ‘‘دوست‘‘ اور بعض میں ‘‘ایلیا‘‘ کہا گیا ہے۔\nاناجیل میں صحیفہ ملاکی کی اس عبارت میں بھی تحریف کر دی گئی ہے: ’’وہ میرے آگے راہ درست کرے گا۔‘‘ یہاں ’’میرے‘‘ ضمیر متکلم ہے، اس کے بجائے اناجیل میں ضمیر مسیح (علیہ السلام) کی طرف لوٹا دی گئی ہے، چنانچہ لوقا کی عبارت ہے: ’’یہ وہی ہے جس کی بابت لکھا ہے کہ دیکھ میں اپنا پیغمبر تیرے آگے بھیجتا ہوں جو تیری راہ تیرے آگے تیار کرے گا۔‘‘(4)\nموجودہ بائبل کی تحریف شدہ عبارات سے آنے والے نبی کا تعین ناممکن ہے کیونکہ یہ عبارات بائبل ہی کی دیگر عبارات","",{"v":200452,"fn":"(1) کتاب مقدس (مرقس) 1:2-9\n(2) کتاب مقدس (لوقا) 7:26-27\n(3) کتاب مقدس (متی) 11:9-15\n(4) کتاب مقدس (لوقا) 7:27"}],[932,"سے متضاد ہیں جن میں آنے والے نبی کی واضح بشارت دی گئی ہے۔\nاس بحث کا حتمی نتیجہ یہ نکلتا ہے کہ ’’عہد کا رسول‘‘ جس کی بشارت دی گئی ہے، وہ محمد صلی اللہ علیہ وسلم ہی کی ذات گرامی ہے۔ نبی صلی اللہ علیہ وسلم ہی معراج کی رات بیت المقدس کی سرزمین میں ہیکل (مسجد اقصیٰ) تشریف لے گئے تھے۔ اس کے برعکس مسیح (علیہ السلام) اور یوحنا (یحییٰ علیہ السلام) دونوں اسی سرزمین میں پیدا ہوئے تھے اور وہیں انھوں نے پرورش پائی۔ محمد صلی اللہ علیہ وسلم ہی کو بائبل کے مختلف نسخوں میں ’’ختنے والا پیغمبر‘‘ قرار دیا گیا ہے جنھوں نے اپنی امت کو ختنے کی ترغیب دی اور اس عمل کو فطری ہدایت ٹھہرایا ہے اور مسلمان اس وقت سے آج تک اس پر عمل پیرا ہیں۔(1)","",{"v":200453,"fn":"(1) هل بشر الكتاب المقدس بمحمد صلی اللہ علیہ وسلم، ص: 115-122"}],[933,"خاتم النبیین صلی اللہ علیہ وسلم کی بعثت و صداقت قرآن مجید میں اللہ تعالیٰ نے فرمایا:\n﴿مَا كَانَ مُحَمَّدٌ أَبَا أَحَدٍ مِنْ رِجَالِكُمْ وَلَٰكِنْ رَسُولَ اللَّهِ وَخَاتَمَ النَّبِيِّينَ ۗ وَكَانَ اللَّهُ بِكُلِّ شَيْءٍ عَلِيمًا﴾\n’’محمد (صلی اللہ علیہ وسلم) تمھارے مردوں میں سے کسی کے باپ نہیں ہیں، اور لیکن وہ اللہ کے رسول اور خاتم النبیین ہیں، اور اللہ ہر شے کو خوب جاننے والا ہے۔‘‘ (الأحزاب 33:40)","",{"v":200454}],[934,"خاتم النبیین صلی اللہ علیہ وسلم کی بعثت و صداقت قرآن کی مذکورہ آیت کی صداقت بائبل سے ہوتی ہے:\n﴿قَالَ لَهُمْ يَسُوعُ أَمَا قَرَأْتُمْ قَطُّ فِي الْكُتُبِ: الْحَجَرُ الَّذِي رَفَضَهُ الْبَنَّاؤُونَ هُوَ قَدْ صَارَ رَأْسَ الزَّاوِيَةِ﴾\n’’یسوع نے ان سے کہا کیا تم نے کتاب مقدس میں کبھی نہیں پڑھا کہ جس پتھر کو معماروں نے ردّ کیا، وہی کونے کے سرے کا پتھر ہو گیا۔‘‘\nکتاب مقدس (متی) 21:42","",{"v":200455}],[935,"§انجیل کی بشارات\nانجیل (Evangel) یونانی لفظ euangelion کا معرب ہے۔ اس کا لفظی ترجمہ ہے: ’’خوشخبری‘‘۔ یہ لفظ غالباً براستہ حبش (ایتھوپیا) عربی میں آیا۔ نئے عہد نامہ میں اس لفظ کا یہی مفہوم (خوشخبری) ہے۔ کسی آیت میں اس کا مطلب ’’کتاب‘‘ یا ’’صحیفہ‘‘ نہیں ہے۔ 150ء کے بعد اس لفظ کو کتاب (نیا عہد نامہ) کے لیے استعمال کیا جانے لگا۔ یہ لفظ نئے عہد نامہ یونانی میں تقریباً سو مرتبہ استعمال ہوا ہے اور پروٹسٹنٹ اردو ترجمہ میں صرف گیارہ مرتبہ۔ باقی جگہ اس کا متبادل اردو لفظ ’’خوشخبری‘‘ درج کیا گیا ہے۔ (کیتھولک ترجمہ میں ہر جگہ انجیل ہی ہے۔)(1)\n[تصویر: انجیل (عہد نامہ جدید) کا ایک قدیم نسخہ]\nجس طرح تورات اور دیگر انبیائے بنی اسرائیل کے صحیفوں میں یہود نے بکثرت تحریف کر ڈالی، اسی طرح اناجیل اربعہ میں بھی عیسائیوں نے تحریف کر کے کلام الٰہی اور اس کی تعلیمات کو مسخ کر دیا، تاہم تحریف و ترمیم کے باوجود اناجیل میں اب بھی ایسے اشارات بکثرت ملتے ہیں جن سے محمد رسول اللہ صلی اللہ علیہ وسلم کی بعثت اور ختم نبوت کی تصدیق ہوتی ہے۔ اس سلسلے میں انجیل کی پیش گوئیاں ملاحظہ کیجیے:\n§انجیل کی پہلی پیش گوئی\n’’اور یوحنا کی گواہی یہ ہے کہ جب یہودیوں نے یروشلم سے کاہن اور لاوی یہ پوچھنے کو اُس کے پاس بھیجے کہ تو کون ہے؟ تو اُس نے اقرار کیا اور انکار نہ کیا بلکہ اقرار کیا کہ میں تو مسیح نہیں ہوں۔ اُنھوں نے اُس سے پوچھا پھر کون ہے؟ کیا تو ایلیاہ ہے؟ اُس نے کہا میں نہیں ہوں۔ کیا تو وہ نبی ہے؟ اُس نے جواب دیا کہ نہیں۔ پس اُنھوں نے اُس سے کہا پھر تو ہے کون؟ تاکہ ہم اپنے بھیجنے والوں کو","",{"v":200456,"fn":"(1) قاموس الکتاب، ص: 93","im":["v2_p456.jpg"]}],[936,"جواب دیں۔ تو اپنے حق میں کیا کہتا ہے؟ اُس نے کہا میں جیسا یسعیاہ نبی نے کہا ہے بیابان میں ایک پکارنے والے کی آواز ہوں کہ تم خداوند کی راہ کو سیدھا کرو۔ یہ فریسیوں کی طرف سے بھیجے گئے تھے۔ اُنھوں نے اُس سے یہ سوال کیا کہ اگر تو نہ مسیح ہے نہ ایلیاہ نہ وہ نبی تو پھر بپتسمہ کیوں دیتا ہے؟‘‘(1)\nمندرجہ بالا اقتباس میں ’’لاوی‘‘ کا نام آیا ہے۔ اس کے بارے میں یہ جان لینا چاہیے کہ درحقیقت لاوی (Levi) حضرت یعقوب علیہ السلام کے بارہ بیٹوں میں سے ایک بیٹے کا نام ہے۔ بعد میں لاوی کی اولاد میں سے یہودی علماء (احبار) کو لاوی کہا جانے لگا، چنانچہ اس حوالے سے بائبل کی ایک کتاب بھی احبار (Leviticus) کہلاتی ہے۔ بائبل کے مطابق ہارون علیہ السلام ’’بنی اسرائیل کے پہلے سردار کاہن‘‘ (First High Priest) تھے۔ ان کے کاہنوں (Priests) اور احبار کے لیے ضروری تھا کہ وہ بنو لاوی بلکہ بنو ہارون میں سے ہوں۔(2)\nبنو ہارون کی نسبت ہارون علیہ السلام سے ہے۔ وہ سیدنا موسیٰ علیہ السلام کے بڑے بھائی تھے۔ وہ موسیٰ علیہ السلام کی ولادت سے تین سال پہلے پیدا ہوئے تھے۔ موسیٰ علیہ السلام کی خواہش پر اللہ تعالیٰ نے یہ کہہ کر ان کو نبی مامور فرمایا: ﴿اذْهَبْ أَنْتَ وَأَخُوكَ بِآيَاتِي وَلَا تَنِيَا فِي ذِكْرِي ۝ اذْهَبَا إِلَىٰ فِرْعَوْنَ إِنَّهُ طَغَىٰ﴾ ’’تم اور تمھارا بھائی میرے (دیے ہوئے) معجزات کے ساتھ جاؤ اور میرے ذکر میں سستی نہ کرنا۔ تم دونوں فرعون کی طرف جاؤ، بے شک وہ سرکش ہو گیا ہے۔‘‘ یوں حضرت ہارون علیہ السلام کو بھی جو فرعون کی مجلس وزراء کے رکن تھے، منصب رسالت سپرد ہوا۔ ہر چند وہ دیگر انبیائے بنی اسرائیل کی طرح شریعت موسوی ہی کے تابع تھے۔ حضرت موسیٰ علیہ السلام کی عدم موجودگی میں جب یہودیوں نے سامری کے کہنے پر سنہرے بچھڑے کی پوجا شروع کر دی تو ہارون علیہ السلام نے انھیں اس سے منع کیا۔\n[تصویر: مقام ہارون علیہ السلام (جبل ہور)]\nمحرفین تورات نے اس موقع پر خواہ مخواہ ہارون علیہ السلام کو گوسالہ پرستی (بچھڑے کی پوجا) میں ملوث کرنے کی ناپاک کوشش کی مگر قرآن حکیم نے ان کی پیغمبرانہ عظمت پوری طرح محفوظ رکھی۔\nدشت تیہ (صحرائے سینا) میں بنی اسرائیل کی چالیس سالہ صحرا نوردی کے دوران میں ہارون علیہ السلام نے وفات پائی اور جبل ہور پر دفن ہوئے۔ اس وقت ان کی عمر 123 برس تھی۔(4)","",{"v":200457,"fn":"(1) کتاب مقدس (یوحنا) 1:19-25\n(2) قاموس الکتاب، ص: 853,854\n(3) طٰہٰ 20:42,43\n(4) اردو دائرۃ معارف اسلامیہ: 23/83,84، اطلس القرآن (اردو)، ص: 145","im":["v2_p457.jpg"]}],[937,"’’وہ نبی‘‘ کون؟\nیوحنا (یحییٰ علیہ السلام) سے یہودیوں نے تین افراد کے متعلق پوچھا: مسیح، ایلیاہ اور ’’وہ نبی‘‘۔ ’’وہ نبی‘‘ اُن کے درمیان اتنا مشہور تھا کہ اُنھوں نے اس کی مزید وضاحت ضروری نہیں سمجھی۔ یہودی اخنوخ (ادریس)، یعقوب، موسیٰ، داود اور دیگر انبیاء علیہم السلام کی بشارات کی وجہ سے ایک ایسے نبی کے منتظر تھے جو نبی ہونے کے ساتھ ساتھ صاحب اختیار و اقتدار بھی ہوگا۔ اُس کی آمد کی صورت میں وہ اپنی نشاۃ ثانیہ اور دوبارہ غلبہ دیکھ رہے تھے۔ اس کے بارے میں فرمان باری تعالیٰ ہے:\n﴿وَلَمَّا جَاءَهُمْ كِتَابٌ مِنْ عِنْدِ اللَّهِ مُصَدِّقٌ لِمَا مَعَهُمْ وَكَانُوا مِنْ قَبْلُ يَسْتَفْتِحُونَ عَلَى الَّذِينَ كَفَرُوا فَلَمَّا جَاءَهُمْ مَا عَرَفُوا كَفَرُوا بِهِ ۚ فَلَعْنَةُ اللَّهِ عَلَى الْكَافِرِينَ﴾\n’’اور جب ان کے پاس اللہ کے ہاں سے ایک کتاب آگئی جو اس (کتاب) کی تصدیق کرنے والی ہے جو ان کے پاس ہے، حالانکہ اس سے پہلے وہ ان لوگوں کے خلاف (رسول موعود کے ذریعے سے) فتح طلب کیا کرتے تھے جنھوں نے کفر کیا، پھر جب ان کے پاس وہ (رسول برحق) آگیا جسے انھوں نے پہچان لیا تو انھوں نے اس کا انکار کر دیا، پس کافروں پر اللہ کی لعنت ہے۔‘‘\nاس آیت مبارک میں اللہ تعالیٰ نے یہودیوں کی گھٹیا ذہنیت بے نقاب کی ہے اور بتایا ہے کہ رسول اللہ صلی اللہ علیہ وسلم کے ظہور مبارک اور نزول قرآن سے پہلے یہودیوں کا طرز عمل یہ تھا کہ جب وہ اپنے مشرک دشمنوں سے جنگ کرتے تو اس رسول کی تشریف آوری کے وسیلے سے کافروں پر فتح کی دعا مانگا کرتے تھے اور کہتے تھے کہ اب اس آخری زمانے میں اللہ کے ایک نبی مبعوث ہوں گے تو ہم ان کے ساتھ مل کر تم سے لڑائی کریں گے اور تمھیں اسی طرح نیست و نابود کر دیں گے جس طرح عاد اور ارم کی قوموں کو تباہ و برباد کر دیا گیا تھا...... لیکن جب رسول اللہ صلی اللہ علیہ وسلم کا ظہور اور قرآن کریم نازل ہوا تو ان کا رویہ بدل گیا۔\nمحمد بن اسحاق نے ابن عباس رضی اللہ عنہما سے روایت کیا ہے کہ رسول اللہ صلی اللہ علیہ وسلم کی بعثت سے پہلے یہود آپ کے وسیلے سے اوس اور خزرج کے خلاف مدد طلب کیا کرتے تھے لیکن اللہ تعالیٰ نے جب آپ کو عربوں میں مبعوث فرما دیا تو انھوں نے اپنی باتوں کے برعکس عناد اور کفر کی راہ اختیار کر لی۔ معاذ بن جبل رضی اللہ عنہ اور خاندان بنو سلمہ کے بشر بن براء بن معرور رضی اللہ عنہ نے ان سے کہا: اے گروہ یہود! اللہ سے ڈرو اور اسلام قبول کر لو، جب ہم مشرک تھے تو تم محمد صلی اللہ علیہ وسلم\n۱ البقرة 2:89","",{"v":200458}],[938,"کے وسیلے سے ہمارے خلاف مدد مانگا کرتے تھے اور تمھی بتایا کرتے تھے کہ اس نبی کی بعثت ہونے والی ہے اور تم ان کی نشانیاں بھی بیان کرتے تھے۔ اس کے جواب میں بنو نضیر کے سلام بن مشکم نے کہا: ’’آپ صلی اللہ علیہ وسلم ہمارے پاس کوئی ایسی چیز نہیں لائے جسے ہم پہچانتے ہوں۔ یہ وہ نبی نہیں جن کا ہم تمھارے سامنے ذکر کیا کرتے تھے۔‘‘ تب ان کے بارے میں مذکورہ آیت کریمہ نازل ہوئی۔(1)\nبائبل بھی یہی کہتی ہے:\n’’اور دیکھو یروشلم میں شمعون نام ایک آدمی تھا اور وہ آدمی راستباز اور خدا ترس اور اسرائیل کی تسلی کا منتظر تھا اور روح القدس اُس پر تھا۔‘‘(2)\n’’اُنھوں نے اُس (یسوع) سے کہا یسوع ناصری کا ماجرا جو خدا اور ساری امت کے نزدیک کام اور کلام میں قدرت والا نبی تھا۔ اور سردار کاہنوں اور ہمارے حاکموں نے اُس کو پکڑوا دیا تاکہ اُس پر قتل کا حکم دیا جائے اور اُسے مصلوب کیا جائے اور اُسے مصلوب کیا۔ لیکن ہم کو امید تھی کہ اسرائیل کو مخلصی یہی دے گا۔‘‘(3)\nعیسیٰ علیہ السلام کے معجزات دیکھ کر بعض لوگوں کو یہ غلط فہمی ہو گئی کہ شاید یسوع ہی وہ بادشاہ نبی ہیں جن کے ذریعے سے ہمیں دوبارہ عروج، ترقی اور اقتدار ملنے والا ہے جیسا کہ مذکورہ پیش گوئی میں ہے۔ لیکن عیسیٰ علیہ السلام ہمیشہ اس کی تردید کرتے رہے۔ یہودیوں کے ہاں تو یہ بات واضح تھی کہ مسیح اور نبی منتظر دو جداگانہ شخصیتیں ہیں لیکن عیسائیوں نے اسے خلط ملط کر دیا۔ نتیجہ یہ نکلا کہ اس کی وجہ سے بائبل کی کئی پیش گوئیوں میں تضادات نمایاں ہو گئے۔\nمسیح سے کیا مراد ہے؟\nبنی اسرائیل کے ہاں پرانا طریقہ یہ تھا کہ کسی چیز یا کسی شخص کو جب کسی مقدس مقصد کے لیے مخصوص کیا جاتا تو اُس چیز پر یا اُس شخص کے سر پر تیل مل کر اُسے متبرک (Consecrate) کر دیا جاتا تھا۔ عبرانی میں تیل ملنے کے اس فعل کو مسح کہتے تھے۔ جس شخص پر تیل ملا جاتا تھا، اُسے مسیح یا مسیّا (Messiah) کہا جاتا تھا۔(4) عبادت گاہ کے ظروف اسی طریقے سے مسح کر کے عبادت کے لیے وقف کیے جاتے تھے۔ کاہنوں کو کہانت (Priesthood) کے منصب پر مامور کرتے وقت بھی مسح کیا جاتا تھا۔ بادشاہ اور نبی بھی جب اللہ کی طرف سے بادشاہت یا نبوت کے لیے نامزد کیے جاتے تو انھیں بھی مسح کیا جاتا، چنانچہ بائبل کی رو سے بنی اسرائیل کی تاریخ میں مسیح بکثرت پائے جاتے ہیں۔(5)","",{"v":200459,"fn":"(1) تفسیر ابن کثیر، البقرة 2:89\n(2) کتاب مقدس (لوقا) 2:25\n(3) کتاب مقدس (لوقا) 24:19-21\n(4) The International Standard Bible Encyclopedia, Messiah.\n(5) دیکھیے: کتاب مقدس (سموئیل-1) 26:7-11، کتاب مقدس (زبور) 18:50 و 105:15"}],[939,"یہودی عقائد کی رو سے ہارون (علیہ السلام) کاہن کی حیثیت سے مسیح تھے۔ موسیٰ (علیہ السلام) کاہن اور نبی ہونے کے لحاظ سے، طالوت بادشاہ کے اعتبار سے، حضرت داود (علیہ السلام) بادشاہ اور نبی کے منصب پر فائز ہونے کی وجہ سے اور الیشع (علیہ السلام) نبی کی حیثیت سے مسیح تھے۔ بعد میں یہ بھی ضروری نہ رہا تھا کہ تیل مل کر ہی کسی کو مامور کیا جائے بلکہ محض کسی کا مامور من اللہ ہونا ہی مسیح کا ہم معنی بن گیا۔\nقرآن کریم میں الیشع نبی کا نام الیسع آیا ہے۔(1) طبری کے بیان کے مطابق الیسع علیہ السلام حضرت الیاس علیہ السلام کے چچازاد بھائی تھے۔ وہ الیاس علیہ السلام کے خلیفہ بھی تھے اور ان کے بعد نبی بنے۔ انھوں نے بعلبک میں زندگی گزاری اور وہیں فوت ہوئے۔(2)\n[تصویر: بعلبک کے کھنڈر]\nخدا نے الییاہ (الیاس علیہ السلام) کو حکم دیا:\n’’خداوند نے اُسے فرمایا تو اپنے راستہ لوٹ کر دمشق کے بیابان کو جا اور جب تو وہاں پہنچے تو تو حزائیل کو مسح کر کہ ارام کا بادشاہ ہو۔ اور نمسی کے بیٹے یاہو کو مسح کر کہ اسرائیل کا بادشاہ ہو اور ابیل محولہ کے الیشع بن سافط کو مسح کر کہ تیری جگہ نبی ہو۔‘‘(3)\nان لوگوں میں سے کسی کے سر پر تیل نہیں ملا گیا۔ بس خدا کی طرف سے ان کی ماموریت کا فیصلہ سنا دینا ہی گویا انھیں مسح کر دینا تھا۔ اسرائیلی تصور کے مطابق لفظ مسیح درحقیقت ’’مامور من اللہ‘‘ کا ہم معنی تھا اور انھی معنوں میں","",{"v":200460,"fn":"(1) الأنعام 6:86، صٓ 38:48\n(2) اطلس القرآن (اردو)، ص: 155-159\n(3) کتاب مقدس (سلاطین-1) 19:15,16","im":["v2_p460.jpg"]}],[940,"حضرت عیسیٰ علیہ السلام یا ’’نبی منتظر‘‘ کے لیے استعمال کیا گیا۔ عیسیٰ علیہ السلام ہمیشہ تردید کرتے رہے کہ وہ ’’نبی منتظر‘‘ یا وہ ’’مسیح‘‘ نہیں تھے جن کے ذریعے سے بنی اسرائیل دوبارہ اپنے غلبے کے خواب دیکھ رہے تھے۔\n§عیسیٰ علیہ السلام کا مسیح ہونے سے انکار\n’’پھر یسوع اور اُس کے شاگرد قیصریہ فلپی کے گاؤں میں چلے گئے اور راہ میں اُس نے اپنے شاگردوں سے یہ پوچھا کہ لوگ مجھے کیا کہتے ہیں؟ اُنھوں نے جواب دیا کہ یوحنا بپتسمہ دینے والا اور بعض ایلیاہ اور بعض نبیوں میں سے کوئی۔ اُس نے اُن سے پوچھا لیکن تم مجھے کیا کہتے ہو؟ پطرس نے جواب میں اُس سے کہا تو مسیح ہے۔ پھر اُس نے اُن کو تاکید کی کہ میری بابت کسی سے یہ نہ کہنا۔‘‘(1)\nقابل غور بات یہ ہے کہ اگر یسوع ’’وہی مسیح‘‘ تھے جس کے ذریعے سے بنی اسرائیل اپنے غلبے اور عروج کے خواب دیکھ رہے تھے تو پھر وہ اپنے مسیح ہونے کو چھپا کیوں رہے تھے۔\n[تصویر: فلپی کا خوبصورت علاقہ]","",{"v":200461,"fn":"(1) کتاب مقدس (مرقس) 8:27-30","im":["v2_p461.jpg"]}],[941,"§عیسیٰ علیہ السلام مسیح منتظر نہیں تھے\nدرحقیقت عیسائیوں کے بقول سیدنا عیسیٰ علیہ السلام کا دکھ اٹھانا اور قتل ہونا یقینی تھا، پھر ڈر کیسا؟ یسوع نے تو ان لوگوں کو جو انھیں مسیح منتظر سمجھتے تھے، شیطان تک کہہ دیا:\n’’اُس وقت سے یسوع اپنے شاگردوں پر ظاہر کرنے لگا کہ اُسے ضرور ہے کہ یروشلم کو جائے اور بزرگوں اور سردار کاہنوں اور فقیہوں کی طرف سے بہت دکھ اٹھائے اور قتل کیا جائے اور تیسرے دن جی اٹھے۔ اس پر پطرس اُس کو الگ لے جا کر ملامت کرنے لگا کہ اے خداوند خدا نہ کرے۔ یہ تجھ پر ہرگز نہیں آنے کا۔ اُس نے پھر کر پطرس سے کہا اے شیطان! میرے سامنے سے دور ہو۔ تو میرے لیے ٹھوکر کا باعث ہے کیونکہ تو خدا کی باتوں کا نہیں بلکہ آدمیوں کی باتوں کا خیال رکھتا ہے۔‘‘(1)\nعیسیٰ علیہ السلام ہمیشہ لوگوں کی اس غلط فہمی کی تردید کرتے رہے کہ وہ ’’وہ نبی‘‘ یا اُن کی اصطلاح میں ’’مسیح‘‘ ہیں جس کے ظہور کی صورت میں وہ دوبارہ اپنا غلبہ دیکھ رہے ہیں:\n’’پس جو معجزہ اُس نے دکھایا وہ لوگ اُسے دیکھ کر کہنے لگے جو نبی دنیا میں آنے والا تھا فی الحقیقت یہی ہے۔ پس یسوع یہ معلوم کر کے کہ وہ آکر مجھے بادشاہ بنانے کے لیے پکڑنا چاہتے ہیں پھر پہاڑ پر اکیلا چلا گیا۔‘‘(2)\nاگر حضرت عیسیٰ علیہ السلام ہی مسیح منتظر تھے تو وہ فرار کیوں ہوئے؟ اور اس کے اظہار کے بجائے وہ اکیلے پہاڑ پر کیوں چلے گئے؟ صاف ظاہر ہے وہ خود کو مسیح منتظر نہیں سمجھتے تھے۔\n§مسیح منتظر: محمد صلی اللہ علیہ وسلم\nاس کے برعکس نبی کریم صلی اللہ علیہ وسلم کی تعلیمات سے یہ بات اظہر من الشمس ہے کہ آپ ہی وہ نبی منتظر ہیں جن کا پہلی آسمانی کتابوں میں بار بار ذکر کیا گیا ہے۔ پہلے انبیاء کی کتابوں میں نبی کریم صلی اللہ علیہ وسلم کے بارے میں بشارات کے علاوہ خود قرآن مجید کی تصدیق اس کا بین ثبوت ہے۔ اللہ تعالیٰ فرماتا ہے:\n﴿وَإِذْ أَخَذَ اللَّهُ مِيثَاقَ النَّبِيِّينَ لَمَا آتَيْتُكُمْ مِنْ كِتَابٍ وَحِكْمَةٍ ثُمَّ جَاءَكُمْ رَسُولٌ مُصَدِّقٌ لِمَا مَعَكُمْ لَتُؤْمِنُنَّ بِهِ وَلَتَنْصُرُنَّهُ ۖ قَالَ أَأَقْرَرْتُمْ وَأَخَذْتُمْ عَلَىٰ ذَٰلِكُمْ إِصْرِي ۖ قَالُوا أَقْرَرْنَا ۚ قَالَ فَاشْهَدُوا وَأَنَا مَعَكُمْ مِنَ الشَّاهِدِينَ﴾","",{"v":200462,"fn":"(1) کتاب مقدس (متی) 16:21-23\n(2) کتاب مقدس (یوحنا) 6:14,15"}],[942,"’’اور (یاد کرو) جب اللہ نے تمام نبیوں سے عہد لیا تھا کہ جب میں تمھیں کتاب اور حکمت عطا کروں، پھر تمھارے پاس کوئی رسول آئے جو اس (کتاب) کی تصدیق کرتا ہو جو تمھارے پاس ہے تو تمھیں اس پر ایمان لانا ہوگا اور اس کی مدد کرنی ہوگی۔ اللہ نے فرمایا: کیا تم اقرار کرتے ہو اور اس پر میرا عہد قبول کرتے ہو؟ انھوں نے کہا: ہم نے اقرار کیا۔ اللہ نے فرمایا: تو تم گواہ رہنا اور میں بھی تمھارے ساتھ گواہ ہوں۔‘‘(1)\nسیدنا علی بن ابی طالب اور ان کے عم زاد سیدنا عبداللہ بن عباس رضی اللہ عنہما فرماتے ہیں کہ اللہ تعالیٰ نے جتنے بھی انبیائے کرام مبعوث فرمائے، ان میں سے ہر نبی سے یہ عہد لیا تھا کہ اگر ان کی زندگی میں حضور محمد صلی اللہ علیہ وسلم مبعوث ہوئے تو انھیں آپ پر ضرور ایمان لانا ہوگا اور آپ کی لازماً مدد کرنی ہوگی۔\nاسی طرح اللہ تعالیٰ نے ہر نبی کو یہ بھی حکم دیا کہ وہ اپنی امت کے لوگوں سے عہد لیں کہ اگر ان کی زندگی میں حضور محمد صلی اللہ علیہ وسلم(2) تشریف لے آئیں تو ان کے لیے ضروری ہوگا کہ وہ آپ پر ایمان لائیں اور آپ کی مدد کریں۔ خاتم الانبیاء محمد صلی اللہ علیہ وسلم ہی امام اعظم ہیں۔ آپ صلی اللہ علیہ وسلم کی اطاعت ہر امت کے ہر فرد پر فرض عین ہے۔ آپ کی ذات گرامی تمام انبیاء سے مقدم ہے۔ یہی وجہ ہے کہ جب شب معراج تمام انبیائے کرام بیت المقدس میں جمع ہوئے تو ان کی امامت کا تاج محمد صلی اللہ علیہ وسلم ہی کے سر مبارک پر رکھا گیا تھا۔(3)\nاسی طرح میدان حشر میں بھی اس وقت رسول اکرم صلی اللہ علیہ وسلم ہی کو شفاعت کبریٰ کا اعزاز حاصل ہوگا جب اللہ تعالیٰ اپنے بندوں کے مابین فیصلہ کرنے کے لیے جلوہ افروز ہوگا۔ یہی وہ مقام محمود ہے جو آپ صلی اللہ علیہ وسلم کی ذات کے لیے خاص ہے۔(4)\nعرباض بن ساریہ رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا:\n﴿إِنِّي عَبْدُ اللَّهِ فِي أُمِّ الْكِتَابِ لَخَاتَمُ النَّبِيِّينَ، وَإِنَّ آدَمَ لَمُنْجَدِلٌ فِي طِينَتِهِ، وَسَأُنَبِّئُكُمْ بِتَأْوِيلِ ذَلِكَ، دَعْوَةُ أَبِي إِبْرَاهِيمَ، وَبِشَارَةُ عِيسَىٰ قَوْمَهُ، وَرُؤْيَا أُمِّي الَّتِي رَأَتْ أَنَّهُ خَرَجَ مِنْهَا نُورٌ أَضَاءَتْ لَهُ قُصُورُ الشَّامِ، وَكَذَلِكَ تَرَىٰ أُمَّهَاتُ النَّبِيِّينَ صَلَوَاتُ اللَّهِ عَلَيْهِمْ﴾\n’’میں اللہ کا بندہ ہوں۔ آدم علیہ السلام جب مٹی کا ڈھانچہ تھے، اسی وقت اللہ تعالیٰ نے لوح محفوظ میں میرا نام","",{"v":200463,"fn":"(1) آل عمران 3:81\n(2) تفسیر الطبری، آل عمران 3:81؛ تفسیر ابن کثیر، آل عمران 3:81,82\n(3) صحیح مسلم: 172، مسند احمد: 257/1\n(4) صحیح البخاری: 4712، نیز دیکھیے: (تحفة الأحوذي: 485/8)"}],[943,"خاتم النبیین کی حیثیت سے لکھ دیا تھا۔ میں تمھیں اس کی تفسیر بتاتا ہوں۔ میں اپنے والد ابراہیم علیہ السلام کی دعا ہوں، عیسیٰ علیہ السلام کی اپنی قوم کو دی گئی بشارت ہوں اور اپنی ماں کے خواب کی تعبیر ہوں۔ میری والدہ نے خواب میں دیکھا کہ ان کے وجود سے ایک نور نکلا ہے جس سے شام کے محلات روشن ہو گئے۔ انبیاء علیہم السلام کی مائیں ایسے ہی خواب دیکھا کرتی ہیں۔(1)\n§انجیل کی دوسری پیش گوئی\nحضرت عیسیٰ علیہ السلام نے اپنے شاگردوں کو بتایا:\n’’اور میں باپ سے درخواست کروں گا تو وہ تمھیں دوسرا مددگار بخشے گا کہ ابد تک تمھارے ساتھ رہے۔‘‘(2)\n’’لیکن مددگار یعنی روح القدس جسے باپ میرے نام سے بھیجے گا وہی تمھیں سب باتیں سکھائے گا اور جو کچھ میں نے تم سے کہا ہے وہ سب تمھیں یاد دلائے گا۔‘‘(3)\n’’لیکن جب وہ مددگار آئے گا جس کو میں تمھارے پاس باپ کی طرف سے بھیجوں گا یعنی روح حق جو باپ سے صادر ہوتا ہے تو وہ میری گواہی دے گا۔ اور تم بھی گواہ ہو کیونکہ شروع سے میرے ساتھ ہو۔‘‘(4)\nعیسیٰ علیہ السلام نے مزید فرمایا:\n’’لیکن میں تم سے سچ کہتا ہوں کہ میرا جانا تمھارے لیے فائدہ مند ہے کیونکہ اگر میں نہ جاؤں تو وہ مددگار تمھارے پاس نہ آئے گا لیکن اگر جاؤں گا تو اسے تمھارے پاس بھیج دوں گا۔ مجھے تم سے اور بھی بہت سی باتیں کہنا ہے مگر اب تم ان کی برداشت نہیں کر سکتے۔ لیکن جب وہ یعنی روح حق آئے گا تو تم کو تمام سچائی کی راہ دکھائے گا۔ اس لیے کہ وہ اپنی طرف سے نہ کہے گا لیکن جو کچھ سنے گا وہی کہے گا اور تمھیں آئندہ کی خبریں دے گا۔‘‘(5)\n1 ‘‘مددگار‘‘ یا فارقلیط؟ بائبل کے اردو ترجمے ‘‘کلام مقدس‘‘ (بائبل سوسائٹی، لاہور) کی مذکورہ آیات میں لفظ ‘‘مددگار‘‘ ہے۔ انگریزی بائبل (نیو انٹرنیشنل ورژن) میں اس کے لیے لفظ Counselor ہے جس کے معنی آکسفورڈ ڈکشنری میں صلاح کار، مشیر، قانونی مشیر یا سفارتکار کے لکھے ہیں۔ عربی بائبل میں لفظ الْمُعَزِّی ہے۔ اس کے معنی ‘‘تسلی دینے","",{"v":200464,"fn":"(1) مسند احمد: 128/4\n(2) کتاب مقدس (یوحنا) 14:16\n(3) کتاب مقدس (یوحنا) 14:26\n(4) کتاب مقدس (یوحنا) 15:26,27\n(5) کتاب مقدس (یوحنا) 16:7-13"}],[944,"والے‘‘ اور ‘‘ڈھارس بندھانے والے‘‘ کے ہیں۔ اس کے برعکس ‘‘کلام مقدس‘‘ (شائع کردہ کاتھولک بائبل کمیشن پاکستان) میں ‘‘مددگار‘‘ کے بجائے لفظ ‘‘وکیل‘‘ استعمال ہوا ہے۔ یوں تینوں زبانوں میں الگ الگ مفہوم کے حامل الفاظ استعمال کیے گئے ہیں۔\nامام ابن القیم رحمہ اللہ نے ہدایۃ الحیاری میں انجیل یوحنا کے اقتباسات نقل کرتے ہوئے فرمایا ہے کہ یہاں اصل لفظ ’’بارقلیط‘‘ یا ’’فارقلیط‘‘ ہے۔ اس وقت کی عربی انجیل میں یوحنا باب 14 کی آیت نمبر 16 اس طرح تھی:\nوَأَنَا أَطْلُبُ مِنَ الْآبِ أَنْ يُعْطِيَكُمْ بَارَقَلِيطًا آخَرَ، يَثْبُتُ مَعَكُمْ إِلَى الْأَبَدِ\nاسی باب کی آیت نمبر 26 اس طرح تھی:\nوَالْبَارَقَلِيطُ، رُوحُ الْحَقِّ الَّذِي يُرْسِلُهُ أَبِي، وَهُوَ يُعَلِّمُكُمْ كُلَّ شَيْءٍ وَهُوَ يُذَكِّرُكُمْ كُلَّ مَا قُلْتُ لَكُمْ\nیوحنا باب 16 کی آیات 12 اور 13 اس طرح تھیں:\nإِنَّ لِي كَلَامًا كَثِيرًا أُرِيدُ أَنْ أَقُولَهُ لَكُمْ، وَلَٰكِنَّكُمْ لَا تَسْتَطِيعُونَ حَمْلَهُ، لَٰكِنْ إِذَا جَاءَ رُوحُ الْحَقِّ، ذَاكَ يُرْشِدُكُمْ إِلَىٰ جَمِيعِ الْحَقِّ، لِأَنَّهُ لَيْسَ يَنْطِقُ مِنْ عِنْدِهِ بَلْ يَتَكَلَّمُ بِمَا يَسْمَعُ وَيُخْبِرُكُمْ بِكُلِّ مَا يَأْتِي، وَيُعَرِّفُكُمْ جَمِيعَ مَا لِلْآبِ\nیوحنا باب 14 کی آیت 30 اس طرح تھی:\nقَالَ الْمَسِيحُ: إِنَّ أَرْكُونَ الْعَالَمِ سَيَأْتِي، وَلَيْسَ لِي شَيْءٌ\n’’مسیح علیہ السلام نے کہا: بے شک دنیا کا سردار آئے گا، مجھے کوئی اختیار نہیں۔‘‘(1)\nلیکن جدید عربی بائبل ’’الکتاب المقدس‘‘ میں یہ آیت یوں دی گئی ہے:\nلِأَنَّ رَئِيسَ هَٰذَا الْعَالَمِ يَأْتِي وَلَيْسَ لَهُ فِيَّ شَيْءٌ\n’’کیونکہ اس دنیا کا سردار آتا ہے اور مجھ میں اس کا کچھ نہیں۔‘‘\n’’فارقلیط‘‘ اور ’’محمد‘‘ ہم معنی ہیں\nاس سے واضح ہو جاتا ہے کہ 751ھ/1350ء میں ابن قیم رحمہ اللہ کی وفات کے بعد ان آیات میں صریحاً تحریف","",{"v":200465,"fn":"(1) ہدایۃ الحیاری فی اجوبۃ الیہود والنصاری، ص: 74"}],[945,"کی گئی اور لفظ ’’بارقلیط‘‘ یا ’’فارقلیط‘‘ جس کے معنی ’’محمد‘‘ یا ’’احمد‘‘ بنتے ہیں، کو بدلنے کے لیے مختلف مفہوم کے الفاظ اختیار کرنے کی کوشش کی گئی۔ لیکن کسی ایک ہی لفظ پر اتفاق نہیں ہو سکا۔ نتیجہ یہ ہے کہ اب تک مختلف زبانوں میں مختلف مطالب و مفاہیم کے حامل الفاظ استعمال کیے جا رہے ہیں۔\nاہل کتاب چاہے قدیم ہوں یا جدید، ان کی عادت ہے کہ وہ اپنے تراجم میں ناموں کا بھی ترجمہ کرتے ہیں اور اصل ناموں کے بجائے ان کے معانی بیان کرتے ہیں۔ کبھی کبھی تغیر کے طور پر اس کلام میں، جو ان کے نزدیک خدائی کلام ہے، اپنی جانب سے کچھ بڑھا بھی دیتے ہیں اور دونوں طرح کے کلام میں فرق و امتیاز کے لیے کسی طرح کا کوئی اشارہ بھی نہیں کرتے۔ یہ دونوں باتیں ان کی عادت ثانیہ بن گئی ہیں۔ جو شخص ان مترجمین کے مختلف زبانوں میں پائے جانے والے ترجموں پر غور کرے گا، اسے ہمارے دعوے کی تصدیق کے بہت سے شواہد مل جائیں گے۔\nعیسیٰ علیہ السلام آرامی زبان بولتے تھے، نہ کہ یونانی۔ اس کے بعد اس بات میں کوئی شک نہیں رہتا کہ عیسیٰ علیہ السلام نے جس شخص کی تشریف آوری کی بشارت دی تھی، مترجمین نے اپنی عادت کے مطابق اس کا یونانی میں ترجمہ کر ڈالا۔ یونانی میں یہ لفظ ’’پیرکلوطوس‘‘ تھا جس کے معنی ’’محمد‘‘ اور ’’احمد‘‘ کے قریب ہیں یا یہ لفظ ’’پاراکلی طوس‘‘ تھا۔ اس کے معنی معین و مددگار، کارساز و وکیل کے ہیں۔ دونوں لفظوں میں بہت معمولی سا فرق ہے۔ عربی مترجمین نے اس کو معرب کر کے ’’فارقلیط‘‘ یا ’’بارقلیط‘‘ بنا دیا۔ یہ لفظ چاہے کتنی ہی ارتقائی منازل سے گزرا ہو، یہ بات بہر حال واضح ہے کہ یسوع نے ایک نبی کی بشارت دی تھی۔ کچھ لوگوں نے ظہور محمدی سے پہلے دعویٰ کیا کہ لفظ ’’فارقلیط‘‘ کا مصداق ہم لوگ ہیں، مثلاً: دوسری صدی عیسوی میں\n[تصویر: قدیم مسیحی فرقے ’’مونٹینزم‘‘ کے مرکز پیپوزا کے حجری آثار (ترکی)]\nمونٹینس (Montanus) نامی ایک عیسائی نے، جو بڑا عبادت گزار اور اپنے زمانے کا سب سے بڑا متقی تھا، ایشیائے کوچک میں 177ء کے قریب دعویٰ کیا کہ جس ’’فارقلیط‘‘ کے آنے کا عیسیٰ علیہ السلام وعدہ کر گئے ہیں وہ میں ہی ہوں، چنانچہ بہت سے لوگ اس کے متبع ہو گئے۔(1)\nواضح رہے کہ پاراکلی طوس کا عبرانی مترادف","",{"v":200466,"fn":"(1) اظہار الحق: 1187,1188/4","im":["v2_p466.jpg"]}],[946,"مناحم (mᵉnaḥḥēm) מנחם ہے۔ یونانی زبان میں اس کا تلفظ (para'klētos) Παράκλητος ہے۔ اسے لاطینی میں paracletus اور انگریزی میں paraclete لکھا گیا ہے۔ انگریزی بائبل میں اس کا ترجمہ counselor (صلاح کار)، helper (مددگار) یا comforter (ڈھارس بندھانے والا) کیا گیا ہے۔(1)\n2 ’’ابد تک تمھارے ساتھ رہے‘‘: نبی کریم صلی اللہ علیہ وسلم خاتم النبیین ہیں اور آپ کی نبوت قیامت تک کے لیے ہے۔\n3 ’’جو کچھ میں نے تم سے کہا ہے وہ سب تمھیں یاد دلائے گا‘‘: نبی کریم صلی اللہ علیہ وسلم بار بار اہل کتاب کو یاد دلاتے رہے کہ یسوع (عیسیٰ علیہ السلام) کی تعلیمات کی بنیاد بھی عقیدہ توحید ہی پر تھی۔ قرآن کریم میں اللہ تعالیٰ کا فرمان ہے:\n﴿قُلْ يَا أَهْلَ الْكِتَابِ تَعَالَوْا إِلَىٰ كَلِمَةٍ سَوَاءٍ بَيْنَنَا وَبَيْنَكُمْ أَلَّا نَعْبُدَ إِلَّا اللهَ وَلَا نُشْرِكَ بِهِ شَيْئًا وَلَا يَتَّخِذَ بَعْضُنَا بَعْضًا أَرْبَابًا مِنْ دُونِ اللهِ﴾\n’’آپ کہہ دیجیے: اے اہل کتاب! ایسی بات کی طرف آؤ جو ہمارے اور تمھارے درمیان یکساں ہے، یہ کہ ہم اللہ کے سوا کسی کی عبادت نہ کریں اور اس کے ساتھ کسی کو شریک نہ ٹھہرائیں اور ہم میں سے کوئی اللہ کے سوا کسی کو رب نہ بنائے۔‘‘(2)\n§بائبل میں عقیدہ توحید\nبائبل (عہد نامہ قدیم) میں بھی توحید کی تلقین کی گئی ہے:\n’’میں ہی خداوند ہوں، میرے سوا کوئی دوسرا نہیں۔ میں ہی روشنی کا موجد اور تاریکی کا خالق ہوں۔ میں سلامتی کا بانی اور بلا کو پیدا کرنے والا ہوں۔ میں ہی خداوند یہ سب کچھ کرنے والا ہوں۔‘‘(3)\n’’سن اے اسرائیل! خداوند ہمارا خدا ایک ہی خداوند ہے۔ تو اپنے سارے دل اور اپنی ساری جان اور اپنی ساری طاقت سے خداوند اپنے خدا سے محبت رکھ۔‘‘(4)\nعہد نامہ جدید میں بھی یہی تعلیمات نظر آتی ہیں:\n’’اے اسرائیل سن! خداوند ہمارا خدا ایک ہی خداوند ہے۔ اور تو خداوند اپنے خدا سے اپنے سارے دل اور اپنی ساری جان اور اپنی ساری عقل اور اپنی ساری طاقت سے محبت رکھ۔‘‘(5)\n’’نعمتیں تو طرح طرح کی ہیں مگر روح ایک ہی ہے۔ اور خدمتیں بھی طرح طرح کی ہیں مگر خداوند ایک ہی ہے۔ اور تاثیریں بھی طرح طرح کی ہیں مگر خدا ایک ہی ہے جو سب میں ہر طرح کا اثر پیدا","",{"v":200467,"fn":"(1) وکی پیڈیا انسائیکلوپیڈیا\n(2) آل عمران 3:64\n(3) کتاب مقدس (یسعیاہ) 45:6,7\n(4) کتاب مقدس (استثنا) 6:4,5\n(5) کتاب مقدس (مرقس) 12:29,30"}],[947,"6 ’’وہ اپنی طرف سے نہ کہے گا لیکن جو کچھ سنے گا وہی کہے گا‘‘: قرآن مجید میں بھی نبی کریم صلی اللہ علیہ وسلم کی ایک بڑی صفت یہ بیان کی گئی ہے کہ آپ اپنی طرف سے کچھ نہیں کہتے بلکہ وحی الٰہی کے مطابق کلام کرتے ہیں۔ اللہ تعالیٰ کا فرمان ہے:\n﴿وَمَا يَنْطِقُ عَنِ الْهَوَىٰ ۝ إِنْ هُوَ إِلَّا وَحْيٌ يُوحَىٰ ۝﴾\n’’اور وہ اپنی خواہش سے نہیں بولتے۔ وہ تو صرف وحی ہے جو نازل کی جاتی ہے۔‘‘(1)\n§انجیل کی تیسری پیش گوئی\n’’یسوع نے ان سے کہا کیا تم نے کتاب مقدس میں کبھی نہیں پڑھا کہ جس پتھر کو معماروں نے رد کیا، وہی کونے کے سرے کا پتھر ہو گیا۔ یہ خداوند کی طرف سے ہوا اور ہماری نظر میں عجیب ہے؟‘‘(2)\n’’کونے کے سرے کا پتھر‘‘: اس سے مراد ختم نبوت ہے۔ کسی دوسرے نبی نے خاتم الانبیاء ہونے کا کبھی دعویٰ نہیں کیا، لہٰذا یہ بات صرف امام الانبیاء نبی آخر الزمان حضور محمد صلی اللہ علیہ وسلم ہی کے لیے کہی گئی ہے۔ فرمان باری تعالیٰ ہے:\n﴿مَا كَانَ مُحَمَّدٌ أَبَا أَحَدٍ مِنْ رِجَالِكُمْ وَلَٰكِنْ رَسُولَ اللهِ وَخَاتَمَ النَّبِيِّينَ وَكَانَ اللهُ بِكُلِّ شَيْءٍ عَلِيمًا ۝﴾\n’’محمد (صلی اللہ علیہ وسلم) تمھارے مردوں میں سے کسی کے باپ نہیں، لیکن وہ اللہ کے رسول اور خاتم النبیین ہیں اور اللہ ہر شے کو خوب جاننے والا ہے۔‘‘(3)\nرسول اللہ صلی اللہ علیہ وسلم نے آج سے چودہ صدیاں پہلے اپنے بارے میں بعینہ یہی مثال دی تھی جو مذکورہ پیش گوئی میں موجود ہے۔ ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\nإِنَّ مَثَلِي وَمَثَلَ الْأَنْبِيَاءِ مِنْ قَبْلِي كَمَثَلِ رَجُلٍ بَنَىٰ بَيْتًا فَأَحْسَنَهُ وَأَجْمَلَهُ إِلَّا مَوْضِعَ لَبِنَةٍ مِنْ زَاوِيَةٍ، فَجَعَلَ النَّاسُ يَطُوفُونَ بِهِ وَيَعْجَبُونَ لَهُ وَيَقُولُونَ: هَلَّا وُضِعَتْ هَٰذِهِ اللَّبِنَةُ؟ قَالَ: فَأَنَا اللَّبِنَةُ، وَأَنَا خَاتَمُ النَّبِيِّينَ\n’’میری اور مجھ سے پہلے انبیاء کی مثال ایسی ہے جیسے ایک شخص نے ایک گھر بنایا اور اس میں ہر طرح کی زینت پیدا کی لیکن ایک کونے میں ایک اینٹ کی جگہ باقی رہ گئی۔ اب لوگ آتے ہیں، مکان کو چاروں طرف سے گھوم پھر کر دیکھتے ہیں اور خوش ہوتے ہیں لیکن وہ یہ بھی کہتے جاتے ہیں کہ یہاں ایک اینٹ","",{"v":200470,"fn":"(1) النجم 53:3,4\n(2) کتاب مقدس (متی) 21:42\n(3) الاحزاب 33:40"}],[948,"کیوں نہ رکھی گئی؟ تو (سن لو!) میں ہی وہ اینٹ ہوں اور میں خاتم النبیین ہوں۔‘‘(1)\nایک اور حدیث میں نبی اکرم صلی اللہ علیہ وسلم نے فرمایا:\nفُضِّلْتُ عَلَى الْأَنْبِيَاءِ بِسِتٍّ، وَخُتِمَ بِيَ النَّبِيُّونَ\n’’مجھے انبیاء علیہم السلام پر چھ باتوں کی وجہ سے فضیلت دی گئی، (ان میں سے چھٹی بات یہ ہے کہ) میرے بعد نبیوں (کے سلسلے) کو ختم کر دیا گیا۔‘‘(2)\nاسی طرح جبیر بن مطعم رضی اللہ عنہ سے روایت ہے، انھوں نے کہا کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو یہ ارشاد فرماتے ہوئے سنا:\nإِنَّ لِي أَسْمَاءً: أَنَا مُحَمَّدٌ، وَأَنَا أَحْمَدُ، وَأَنَا الْمَاحِي الَّذِي يَمْحُو اللهُ بِيَ الْكُفْرَ، وَأَنَا الْحَاشِرُ الَّذِي يُحْشَرُ النَّاسُ عَلَىٰ قَدَمَيَّ، وَأَنَا الْعَاقِبُ الَّذِي لَيْسَ بَعْدَهُ أَحَدٌ\n’’بے شک میرے کئی نام ہیں: میں محمد ہوں، میں احمد ہوں، میں ماحی ہوں جس کے ذریعے اللہ تعالیٰ کفر کو مٹا دے گا، میں حاشر ہوں کہ لوگوں کو میرے قدموں پر جمع کیا جائے گا اور میں عاقب ہوں کہ میرے بعد کوئی نبی نہیں ہوگا۔‘‘(3)،(4)\nاللہ تبارک و تعالیٰ نے اپنی کتاب میں اور رسول اللہ صلی اللہ علیہ وسلم نے اپنی سنت متواترہ میں یہ خبر دی ہے کہ آپ کے بعد قیامت تک کوئی نبی نہیں آئے گا تاکہ لوگوں کو معلوم ہو جائے کہ آپ کے بعد جو بھی نبوت کا دعویٰ کرے، وہ کذاب، افترا پرداز، دجال، خود گمراہ اور دوسروں کو گمراہ کرنے والا ہے، چاہے وہ کیسے ہی خرق عادت امور اور کیسی ہی شعبدہ بازیاں دکھائے اور مختلف انواع و اقسام کے جادو اور طلسمات کا مظاہرہ کرے۔ اہل عقل کے نزدیک یہ سب گمراہی کی باتیں ہیں جیسا کہ اللہ سبحانہ و تعالیٰ نے یمن میں نبوت کا جھوٹا دعویٰ کرنے والے اسود عنسی اور مسیلمہ کذاب کی زبان پر ایسے فاسد احوال اور بے کار اقوال جاری فرما دیے تھے جن سے ہر عقل مند اور صاحب فہم و بصیرت نے یہ معلوم کر لیا تھا کہ نبوت کا دعویٰ کرنے والے یہ دونوں شخص پرلے درجے کے جھوٹے اور گمراہ ہیں۔ اللہ تعالیٰ ان پر لعنت فرمائے۔ ایسے جھوٹے مدعیان نبوت میں سے ہر ایک کے ساتھ اللہ تعالیٰ ایسے امور پیدا فرما دیتا ہے جس سے علماء اور مومن فوراً معلوم کر لیتے ہیں کہ یہ شخص نبوت کا جھوٹا دعوے دار ہے۔ اس کے برعکس حضرات انبیائے کرام علیہم السلام کے علم و فہم کا مرکز براہ راست اللہ سبحانہ و تعالیٰ کی ذات ہوتی ہے، ان کے اقوال و افعال اللہ جل جلالہ کے","",{"v":200471,"fn":"(1) صحیح البخاری: 3535\n(2) صحیح مسلم: 523\n(3) صحیح البخاری: 4896\n(4) صحیح مسلم: 2354، واللفظ لہ"}],[949,"حکم اور منشا کے مطابق ہوتے ہیں، ان کی زندگی کی ہر ادا اپنے پروردگار کی عبادت میں خلوص سے ممیز ہوتی ہے اور ان کا کردار انتہائی نیکی، راست بازی، رشد و فلاح اور عدل و استقامت پر مبنی ہوتا ہے۔ بہر حال انجیل کی مذکورہ پیش گوئی کے مصداق خاتم الانبیاء سیدنا محمد مصطفیٰ صلی اللہ علیہ وسلم ہی کی ذات گرامی ہے، آپ کے سوا اس کا مصداق اور کوئی نہیں ہو سکتا۔\n§انجیل کی چوتھی پیش گوئی\n’’خدا کی بادشاہی‘‘: بائبل میں مذکور انبیاء کی تعلیمات میں ’’خدا کی بادشاہی‘‘ یا ’’آسمان کی بادشاہی‘‘ کا بار بار ذکر ملتا ہے بلکہ ان کی دعوت کا بڑا مقصد ہی خدا کی بادشاہی کا اعلان کرنا تھا۔ خدا کی بادشاہی سے مراد نبوت ہے جس کے بارے میں خداوند نے موسیٰ (علیہ السلام) کے ذریعے سے کہا کہ یہ بنی اسرائیل سے لے کر ان کے بھائیوں بنی اسماعیل کو دے دی جائے گی۔ انجیل میں لکھا ہے:\n’’اس لیے میں تم سے کہتا ہوں کہ خدا کی بادشاہی تم سے لے لی جائے گی اور اس قوم کو جو اس کے پھل لائے دے دی جائے گی اور جو اس پتھر پر گرے گا ٹکڑے ٹکڑے ہو جائے گا لیکن جس پر وہ گرے گا اسے پیس ڈالے گا۔‘‘(1)\n’’خدا کی بادشاہی تم سے لے لی جائے گی اور اس قوم کو جو اس کے پھل لائے دے دی جائے گی‘‘: یہی بات زبور میں کہی گئی ہے: ’’صادق زمین کے وارث ہوں گے۔‘‘(2)\nقرآن مجید بھی اس حقیقت کی تصدیق کرتا ہے۔ فرمان باری تعالیٰ ہے:\n﴿وَلَقَدْ كَتَبْنَا فِي الزَّبُورِ مِنْ بَعْدِ الذِّكْرِ أَنَّ الْأَرْضَ يَرِثُهَا عِبَادِيَ الصَّالِحُونَ ۝﴾\n’’اور بلاشبہ ہم زبور میں نصیحت کے بعد یہ لکھ چکے ہیں کہ بے شک میرے نیک بندے زمین کے وارث ہوں گے۔‘‘(3)\nمفسرین کے ایک قول کے مطابق ’’الْاَرْضَ‘‘ زمین کے یہ معنی ہو سکتے ہیں کہ ہم نے کتاب زبور (صحیفہ داود نبی علیہ السلام) میں نصیحت کے بعد یہ لکھ رکھا ہے کہ زمین کے مالک میرے نیک بندے ہوں گے۔ اس صورت میں یہ آیت مومنین کے حق میں ایک بشارت دنیوی نعمت، یعنی زمینی بادشاہت کی ہوگی اور اگر ’’الْاَرْضَ‘‘ سے مراد ارض موعود لی جائے، یعنی ملک شام (جیسا کہ بہت سے اہل تفسیر نے یہ مراد بھی ہے)، تب تو یہ پیش گوئی عہد صحابہ میں پوری طرح پوری ہو کر رہی۔(4)","",{"v":200472,"fn":"(1) کتاب مقدس (متی) 21:43,44\n(2) کتاب مقدس (زبور) 37:29\n(3) الانبیاء 21:105\n(4) تفسیر ماجدی، الانبیاء 21:105"}],[950,"دوسری جگہ اللہ تعالیٰ نے فرمایا:\n﴿وَعَدَ اللهُ الَّذِينَ آمَنُوا مِنْكُمْ وَعَمِلُوا الصَّالِحَاتِ لَيَسْتَخْلِفَنَّهُمْ فِي الْأَرْضِ كَمَا اسْتَخْلَفَ الَّذِينَ مِنْ قَبْلِهِمْ وَلَيُمَكِّنَنَّ لَهُمْ دِينَهُمُ الَّذِي ارْتَضَىٰ لَهُمْ وَلَيُبَدِّلَنَّهُمْ مِنْ بَعْدِ خَوْفِهِمْ أَمْنًا ۚ يَعْبُدُونَنِي لَا يُشْرِكُونَ بِي شَيْئًا ۚ وَمَنْ كَفَرَ بَعْدَ ذَٰلِكَ فَأُولَٰئِكَ هُمُ الْفَاسِقُونَ ۝﴾\n’’تم میں سے جو ایمان لائے اور انھوں نے نیک عمل کیے، اللہ نے ان لوگوں سے وعدہ کیا ہے کہ وہ انھیں زمین میں ضرور خلافت دے گا، جیسے اس نے ان سے پہلے لوگوں کو خلافت دی تھی اور ان کے لیے ضرور ان کا وہ دین محکم و پائیدار کر دے گا جو اس نے ان کے لیے چنا اور یقیناً وہ ان کی حالت خوف بدل کر انھیں ضرور امن دے گا۔ وہ میری عبادت کریں گے، میرے ساتھ کسی چیز کو شریک نہیں ٹھہرائیں گے اور جو کوئی اس کے بعد کفر کرے تو وہی لوگ فاسق ہیں۔‘‘(1)\nعلاوہ ازیں خود رسول اللہ صلی اللہ علیہ وسلم کا ارشاد گرامی ہے:\nإِنَّ اللهَ زَوَىٰ لِيَ الْأَرْضَ فَرَأَيْتُ مَشَارِقَهَا وَمَغَارِبَهَا، وَإِنَّ أُمَّتِي سَيَبْلُغُ مُلْكُهَا مَا زُوِيَ لِي مِنْهَا، وَأُعْطِيتُ الْكَنْزَيْنِ الْأَحْمَرَ وَالْأَبْيَضَ\n’’بے شک اللہ نے میرے لیے زمین کو سمیٹ دیا تو میں نے اس کے مشارق اور مغارب کو دیکھا اور اس میں کوئی شک نہیں کہ عنقریب میری امت کی بادشاہت وہاں تک پہنچے گی جہاں تک میرے لیے زمین سمیٹی گئی اور مجھے دو خزانے دیے گئے ہیں: سرخ (سونا) اور سفید (چاندی)۔‘‘(2)\nجب عدی بن حاتم رضی اللہ عنہ رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے تو آپ صلی اللہ علیہ وسلم نے دریافت فرمایا: أَتَعْرِفُ الْحِيرَةَ؟ ’’کیا تم حیرہ کو جانتے ہو؟‘‘ انھوں نے عرض کی کہ میں اسے جانتا تو نہیں لیکن اس کے بارے میں سن رکھا ہے، آپ صلی اللہ علیہ وسلم نے فرمایا:\nفَوَالَّذِي نَفْسِي بِيَدِهِ لَيُتِمَّنَّ اللهُ هَٰذَا الْأَمْرَ حَتَّىٰ تَخْرُجَ الظَّعِينَةُ مِنَ الْحِيرَةِ حَتَّىٰ تَطُوفَ بِالْبَيْتِ فِي غَيْرِ جِوَارِ أَحَدٍ وَلَتُفْتَحَنَّ كُنُوزُ كِسْرَىٰ ابْنِ هُرْمُزَ\n’’اس ذات اقدس کی قسم جس کے ہاتھ میں میری جان ہے! اللہ تعالیٰ اس دین کو ضرور مکمل فرمائے گا حتیٰ کہ ہودج میں سوار ایک عورت حیرہ سے سفر کرتی ہوئی آئے گی اور کسی کی پناہ لیے بغیر وہ بیت اللہ کا طواف","",{"v":200473,"fn":"(1) النور 24:55\n(2) صحیح مسلم: 2889"}],[951,"کرے گی اور تم کسریٰ بن ہرمز کے خزانے ضرور فتح کر لو گے۔‘‘\nمیں نے وضاحت چاہی: کسریٰ (خسرو پرویز) بن ہرمز؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ہاں! کسریٰ بن ہرمز! اور مال کی اس قدر فراوانی ہو جائے گی کہ اسے کوئی قبول کرنے والا نہ ہوگا۔(1)\nمختلف انبیاء ’’خدا کی بادشاہی‘‘ کی بشارت دیتے رہے:\n’’شریعت اور انبیاء یوحنا تک رہے۔ اس وقت سے خدا کی بادشاہی کی خوشخبری دی جاتی ہے اور ہر ایک زور مار کر اس میں داخل ہوتا ہے۔‘‘(2)\n§یحییٰ اور عیسیٰ علیہما السلام کا اعلان\nیوحنا نبی نے یہودیہ کے بیابان میں منادی کی:\n’’توبہ کرو کیونکہ آسمان کی بادشاہی نزدیک آ گئی ہے۔‘‘(3)\nیہودیہ (یہوداہ) کا پس منظر یہ ہے کہ جب سلیمان بادشاہ (علیہ السلام) کے عہد کے بعد بنی اسرائیل دو سلطنتوں میں بٹ گئے تو عبرانی قبیلے یہوداہ نے بن یمین کے قبیلے سے مل کر جنوبی سلطنت قائم کی جس کا رومی اور یونانی نام یہودیہ (Judaea) ہے۔ رومی فتوحات (63 ق م) کے بعد یہ نام زیادہ وسیع معنوں میں فلسطین بشمول گلیل اور سامریہ کے لیے استعمال ہونے لگا۔ گلیل یا جلیل (Galilee) کے عبرانی معنی ’’حلقہ‘‘ کے ہیں۔ یہ علاقہ فلسطین کے شمال میں اور یردن دریا کے مغرب میں واقع تھا۔ اس پر ہیرودیس انتپاس 4 ق م سے 39ء تک حاکم رہا۔ مسیح (علیہ السلام) کی خدمت (نبوت) کا بیشتر حصہ یہیں گزرا، اس لیے انھیں گلیلی بھی کہا گیا ہے۔ اسی علاقے سے انھوں نے اپنے شاگرد چنے۔ گلیل کی نسبت سے گلیل یا تبریاس کی جھیل مشہور ہے۔(4)\n[تصویر: جھیل تبریاس کے کنارے آباد طبریہ کا شہر]\nجھیل تبریاس یا طبریہ (Sea of Galilee) کے مغربی کنارے پر طبریہ (Tiberias) نامی شہر آباد ہے۔ یہیں 583ھ/1187ء میں(5)","",{"v":200474,"fn":"(1) صحیح البخاری: 3595، مسند احمد: 257/4، واللفظ لہ\n(2) کتاب مقدس (لوقا) 16:16\n(3) کتاب مقدس (متی) 3:2\n(4) قاموس الکتاب، ص: 835,836\n(5) NIV Study bible: Map 2","im":["v2_p474.jpg"]}],[952,"میں جنگ حطین (جنگ طبریہ) میں سلطان صلاح الدین ایوبی نے صلیبیوں کو تاریخی شکست دی جس کے بعد جلد ہی بیت المقدس صلیبیوں سے آزاد کرا لیا گیا۔ ہیرودیس کی یہودیہ کی سلطنت (37 تا 4 ق م) میں تمام فلسطین کا علاقہ اور یردن (دریائے اردن) کے مشرق کے کچھ علاقے بھی شامل تھے۔(1)\nیوحنا (یحییٰ علیہ السلام) کی وفات کے بعد بھی یسوع (عیسیٰ علیہ السلام) آسمان کی بادشاہی کے قریب آنے کا اعلان کرتے رہے:\n’’اس وقت سے یسوع نے منادی کرنا اور یہ کہنا شروع کیا کہ توبہ کرو کیونکہ آسمان کی بادشاہی نزدیک آ گئی ہے۔‘‘(2)\n’’اور یسوع تمام گلیل میں پھرتا رہا اور ان کے عبادت خانوں میں تعلیم دیتا اور بادشاہی کی خوشخبری کی منادی کرتا اور لوگوں کی ہر طرح کی بیماری اور ہر طرح کی کمزوری کو دور کرتا رہا۔‘‘(3)\n’’تھوڑے عرصے کے بعد یوں ہوا کہ وہ منادی کرتا اور خدا کی بادشاہی کی خوشخبری سناتا ہوا شہر شہر اور گاؤں گاؤں پھرنے لگا اور وہ بارہ (حواری) اس کے ساتھ تھے۔‘‘(4)\n’’اس نے ان سے کہا مجھے اور شہروں میں بھی خدا کی بادشاہی کی خوشخبری سنانا ضرور ہے کیونکہ میں اسی لیے بھیجا گیا ہوں۔‘‘(5)\n’’غیر قوموں کی طرف نہ جانا اور سامریوں کے کسی شہر میں داخل نہ ہونا۔ بلکہ اسرائیل کے گھرانے کی کھوئی ہوئی بھیڑوں کے پاس جانا اور چلتے چلتے یہ منادی کرنا کہ آسمان کی بادشاہی نزدیک آ گئی ہے۔‘‘(6)\n’’آسمان کی بادشاہی‘‘ کس کے لیے؟\nعیسائی علماء ’’خدا کی بادشاہی‘‘ یا ’’آسمان کی بادشاہی‘‘ کی مختلف وضاحتیں کرتے ہیں، مثلاً:\n1 عیسائیت کا پھیلنا اور نزول مسیح کے بعد اس کا ساری دنیا میں پھیل جانا۔\n2 کنیسہ (کلیسا) کا ملحدین پر غلبہ۔\n3 یسوع کے خون کی وجہ سے نجات۔\nعیسائی علماء کا یہ کہنا کہ ’’آسمان کی بادشاہی سے مراد عیسائیت کا پھیلنا اور نزول مسیح کے بعد اس کا ساری دنیا میں پھیل جانا ہے‘‘ تو یہ محض ان کا اپنا مفروضہ ہے جس کا حقیقت سے کوئی تعلق نہیں۔ وہ اپنی اس توجیہ کے حق میں","",{"v":200475,"fn":"(1) قاموس الکتاب، ص: 1185-1188\n(2) کتاب مقدس (متی) 4:17\n(3) کتاب مقدس (متی) 4:23\n(4) کتاب مقدس (لوقا) 8:1\n(5) کتاب مقدس (لوقا) 4:43\n(6) کتاب مقدس (متی) 10:5-7"}],[953,"دلیل کے پیش کرنے سے قاصر ہیں۔ اس طرح کی توجیہات باعث تعجب ہیں۔ یورپ میں عرصہ دراز تک کلیسا کا غلبہ رہا لیکن ’’خدا کی بادشاہی‘‘ کا مقصد حاصل نہ ہو سکا۔ کلیسا تو ملحدین پر غلبہ نہیں پا سکا، البتہ ملحدین نے اسے زندگی کے دھارے سے نکال کر دیوار سے ضرور لگا دیا ہے۔\n’’یسوع کے خون کی وجہ سے ان کے پیروکاروں کی نجات‘‘ ایسی توجیہ ہے کہ یسوع نے کبھی اس کا اظہار نہیں کیا۔ یسوع کے قریب ترین ساتھی بھی نہیں جانتے تھے کہ ’’خدا کی بادشاہی‘‘ سے مراد سولی پر جان دے کر انسانوں کے گناہوں کا کفارہ ادا کرنا ہے۔ وہ تو مسیح کی مبینہ موت پر اس لیے غمگین تھے کہ ان کے لیے خلاصی اور نجات کا موقع باقی نہیں رہا۔(1)\nانجیل کی رو سے ’’آسمان کی بادشاہی‘‘ سے یسوع کا سولی پر جان دینا مراد نہیں۔(2) صلیب پر چڑھنے کا واقعہ تو بائبل میں بڑے ذلت آمیز طریقے سے بیان کیا گیا ہے:\n’’مسیح جو ہمارے لیے لعنتی بنا اس نے ہمیں مول لے کر شریعت کی لعنت سے چھڑایا کیونکہ لکھا ہے کہ جو کوئی لکڑی پر لٹکایا گیا وہ لعنتی ہے۔‘‘(3)\nاگر ’’آسمان کی بادشاہی‘‘ سے مراد سولی پر چڑھنا ہی ہے تو یسوع کو خوشی خوشی یہ کام کرنا چاہیے تھا مگر وہ تو انجیل کے مطابق بادل ناخواستہ بھی اس کے لیے تیار نہیں تھے بلکہ اس پر انتہائی مایوس اور غمگین تھے اور اسے ٹالنے کے آرزومند تھے:\n’’اس وقت اس (یسوع) نے ان سے کہا: میری جان نہایت غمگین ہے۔ یہاں تک کہ مرنے کی نوبت پہنچ گئی ہے۔ تم یہاں ٹھہرو اور میرے ساتھ جاگتے رہو۔ پھر ذرا آگے بڑھا اور منہ کے بل گر کر یوں دعا کی کہ اے میرے باپ! اگر ہو سکے تو یہ پیالہ مجھ سے ٹل جائے۔‘‘(4)\nانجیل برناباس کے مطابق یہودا اسخریوطی (چاروں انجیلوں کے مطابق ’’یسوع مسیح‘‘) کے صلیب پر چڑھائے جانے کی المناک تفصیلات کسی طرح ’’آسمانی بادشاہی‘‘ سے مطابقت نہیں رکھتیں۔ متی (Matthew) نے سولی چڑھانے کے آخری لمحات کی تفصیل یوں رقم کی ہے:\nایلی، ایلی، لما شبقتنی؟\n’’اور تیسرے پہر کے قریب یسوع نے بڑی آواز سے چلا کر کہا ایلی، ایلی، لما شبقتنی؟ یعنی اے میرے","",{"v":200476,"fn":"(1) دیکھیے: کتاب مقدس (لوقا) 24:17-21، 23:48,49\n(2) دیکھیے: کتاب مقدس (لوقا) 21:6-31\n(3) کتاب مقدس (گلتیوں کے نام) 3:13\n(4) کتاب مقدس (متی) 26:38,39"}],[954,"[تصویر: گلگتا (آرامی زبان میں ’’کھوپڑی‘‘) نامی چٹان جس کے پاس عیسائیوں کے عقیدے کے مطابق حضرت عیسیٰ علیہ السلام کو صلیب پر چڑھایا گیا]\nخدا! اے میرے خدا! تو نے مجھے کیوں چھوڑ دیا؟ جو وہاں کھڑے تھے ان میں سے بعض نے سن کر کہا یہ ایلیاہ کو پکارتا ہے۔ اور فوراً ان میں سے ایک شخص دوڑا اور اسفنج لے کر سرکہ میں ڈبویا اور سرکنڈے پر رکھ کر اسے پھسایا۔ مگر باقیوں نے کہا ٹھہر جاؤ۔ دیکھیں تو ایلیاہ اسے بچانے آتا ہے یا نہیں۔ یسوع نے پھر بڑی آواز سے چلا کر جان دے دی۔‘‘(1)\nانجیل کے اس اقتباس سے اندازہ کیجیے کہ یسوع (دراصل یہودا اسکریوطی) کس قدر بے بسی کی تصویر بنے ہوئے ہیں اور کتنی حسرت سے پکارتے ہیں: ’’اے میرے خدا! اے میرے خدا! تو نے مجھے کیوں چھوڑ دیا ہے؟‘‘ اگر یسوع کے بھیجے جانے کا مقصد ہی اپنی جان کا نذرانہ پیش کر کے بنو آدم کے گناہوں کا کفارہ ادا کرنا تھا تو وہ اتنے مایوس کیوں تھے؟ کسی عظیم مقصد کی خاطر جان دینے والے تو ہنسی خوشی برضا و رغبت جان جان آفریں کے سپرد کر دیتے ہیں اور ان کی حالت یہ ہوتی ہے؎","",{"v":200477,"fn":"(1) کتاب مقدس (متی) 27:46-50","im":["v2_p477.jpg"]}],[955,"سب کچھ لٹا کے راہ صداقت میں اہل دل\n§یوں خوش ہیں جیسے دولت کونین پا گئے\nیہودا اسخریوطی کو طرح طرح کے نام دیے گئے ہیں۔ اس کے نام یہوداہ اسکریوطی، یہودہ اسکریوطی، یہودا اسکریوطی اور Judas Iscariot بتائے گئے ہیں۔ قاموس الکتاب میں لکھا ہے: ’’یہوداہ اسکریوطی یسوع مسیح کا شاگرد اور شمعون اسکریوطی کا بیٹا تھا۔ عبرانی میں الیش قریتی (اسکریوطی) کے معنی ہیں ‘‘قریت کا آدمی’’۔ ‘‘قریت’’ جنوبی یہوداہ (Judaea) میں ایک مقام تھا۔ بارہ شاگردوں میں سے یہ واحد شاگرد تھا جو گلیلی نہ تھا۔ اس نے تیس روپے (اشرفیاں) لے کر مسیح کو سردار کاہنوں کے حوالے کرا دیا۔ بعد میں جب اسے اپنی غلطی کا احساس ہوا تو وہ سردار کاہنوں کے پاس گیا اور اقرار کیا کہ میں نے ایک بے قصور شخص کو قتل کے لیے پکڑوایا ہے۔ انھوں نے پیسے واپس لینے سے انکار کیا تو وہ انھیں مقدس میں پھینک کر چلا گیا اور جا کر اپنے آپ کو پھانسی دے دی۔‘‘(1)\nجہاں اناجیل اربعہ یسوع مسیح (علیہ السلام) کو صلیب پر چڑھانے کا قصہ بیان کرتی ہیں، وہاں انجیل برناباس کہتی ہے کہ یسوع کے حواری یہودا نے سونے کے تیس ٹکڑے رشوت لے کر ان کی مخبری کر دی مگر جب رومی گورنر کے حکم پر سپاہی یہودا کے ساتھ اس جگہ کے نزدیک پہنچے جہاں یسوع اور ان کے گیارہ شاگرد سو رہے تھے تو جبریل، میکائیل، رفائیل اور اسرافیل فرشتے حکم الٰہی سے آئے اور یسوع کو اٹھا کر آسمان پر لے گئے۔ اور جب یہودا کمرے میں داخل ہوا تو وہ بولی (لب و لہجہ) اور چہرے میں بدل کر یسوع کے مشابہ ہو گیا۔ پھر سپاہی اسی کو پکڑ کر اورشلیم (یروشلم) لے گئے۔ وہ چیختا رہ گیا کہ وہ یہودا اسخریوطی ہے مگر اس کی کسی نے نہیں سنی۔ آخر کار یہودی فریسیوں اور کاہنوں کے اصرار پر اسے سولی پر چڑھا دیا گیا۔(2)\nیہ بیان اس قرآنی تصریح کے عین مطابق ہے:\n﴿وَمَا قَتَلُوهُ وَمَا صَلَّبُوهُ وَلَٰكِنْ شُبِّهَ لَهُمْ ۚ وَإِنَّ الَّذِينَ اخْتَلَفُوا فِيهِ لَفِي شَكٍّ مِنْهُ ۚ مَا لَهُمْ بِهِ مِنْ عِلْمٍ إِلَّا اتِّبَاعَ الظَّنِّ ۚ وَمَا قَتَلُوهُ يَقِينًا ۝ بَلْ رَفَعَهُ اللهُ إِلَيْهِ ۝﴾\n’’اور انھوں نے نہ انھیں (عیسیٰ علیہ السلام) کو قتل کیا اور نہ سولی پر چڑھایا بلکہ انھیں شبہے میں ڈال دیا گیا۔ اور بے شک جنھوں نے عیسیٰ کے بارے میں اختلاف کیا، وہ ضرور ان کے متعلق شک میں ہیں۔ ان لوگوں کے پاس ان کے بارے میں کوئی علم نہیں، سوائے گمان کی پیروی کے، اور انھوں نے یقیناً انھیں قتل نہیں کیا بلکہ اللہ نے انھیں اپنی طرف اٹھا لیا۔‘‘(3)\nاناجیل کے برعکس ابن عباس رضی اللہ عنہما کی ایک روایت میں یہوداہ اسکریوطی کے پاکیزہ کردار پر روشنی ڈالی گئی ہے کہ اس","",{"v":200478,"fn":"(1) قاموس الکتاب، ص: 1186\n(2) انجیل برناباس، فصل 214 تا 217\n(3) النساء 4:157,158"}],[956,"نے ہرگز غداری نہیں کی تھی بلکہ حضرت عیسیٰ علیہ السلام کے حسب خواہش صلیب پر جان دی جبکہ اس کی شکل تبدیل ہو گئی تھی۔(1)\n’’خدا کی بادشاہی‘‘ کے اصل مصداق: محمد صلی اللہ علیہ وسلم\nحضرت یحییٰ اور حضرت عیسیٰ علیہما السلام کی منادی کے بعد ’’خدا کی بادشاہی‘‘ یا ’’آسمان کی بادشاہی‘‘ کے متعلق مسیحی علماء کے دعوے جب بے بنیاد ٹھہرتے ہیں تو اس کا ایک ہی نتیجہ نکلتا ہے کہ ’’خدا کی بادشاہی‘‘ سے مراد آخری نبی حضور محمد صلی اللہ علیہ وسلم کی نبوت ہے جبکہ بائبل میں واضح طور پر ذکر ہے کہ ’’خدا کی بادشاہی‘‘ بنی اسرائیل سے لے کر ایک اور قوم کو دے دی جائے گی۔ اس کی وضاحت پہلے گزر چکی ہے کہ وہ دوسری قوم بنی اسماعیل ہے جن میں ان پیش گوئیوں کے بعد پیغمبر آخر الزمان محمد صلی اللہ علیہ وسلم کا ظہور ہوا۔\n§انجیل کی پانچویں پیش گوئی\nآخری نبی کی آمد کی بشارت: انجیل متی میں آسمان کی بادشاہی کو ایک تاکستان (انگوروں کے باغ) کے مالک سے تشبیہ دی گئی ہے کہ وہ شام کو طے شدہ مزدوری دینے لگا تو اس نے سارا دن یا آدھا دن کام کرنے والوں اور آخری ایک گھنٹہ کام کرنے والوں کو برابر مزدوری دینا چاہی تو پہلوں نے اعتراض کیا۔ اس پر مالک نے کہا کہ میں اپنے مال سے جو چاہوں سو کروں۔ یہ مثال دے کر انجیل میں کہا گیا ہے:\n’’اسی طرح آخر اول ہو جائیں گے اور اول آخر۔‘‘(2)\nاس مثال میں آسمان کی بادشاہی، یعنی نبوت کی طرف یہ کہہ کر اشارہ کیا گیا ہے کہ آخر میں آنے والے نبی کو مرتبے کے لحاظ سے اولیت حاصل ہوگی جیسا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ہے:\nنَحْنُ الْآخِرُونَ السَّابِقُونَ\n’’ہم آخر میں آنے والے سبقت لے جانے والے ہیں۔‘‘(3)\nرسول اللہ صلی اللہ علیہ وسلم کے ایک اور فرمان سے اس کی مزید وضاحت ہوتی ہے۔ عبداللہ بن عمر رضی اللہ عنہما بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا:\nإِنَّمَا بَقَاؤُكُمْ فِيمَا سَلَفَ قَبْلَكُمْ مِنَ الْأُمَمِ كَمَا بَيْنَ صَلَاةِ الْعَصْرِ إِلَىٰ غُرُوبِ الشَّمْسِ،","",{"v":200479,"fn":"(1) تفسیر ابن ابی حاتم، النساء 4:157، تفصیل کے لیے دیکھیے: جلد اول، باب: \"عیسیٰ اور عیسائیت\"\n(2) دیکھیے: کتاب مقدس (متی) 20:1-16\n(3) صحیح البخاری: 238"}],[957,"أُوتِيَ أَهْلُ التَّوْرَاةِ التَّوْرَاةَ، فَعَمِلُوا بِهَا حَتَّىٰ إِذَا انْتَصَفَ النَّهَارُ عَجَزُوا، فَأُعْطُوا قِيرَاطًا قِيرَاطًا، ثُمَّ أُوتِيَ أَهْلُ الْإِنْجِيلِ الْإِنْجِيلَ، فَعَمِلُوا إِلَىٰ صَلَاةِ الْعَصْرِ ثُمَّ عَجَزُوا فَأُعْطُوا قِيرَاطًا قِيرَاطًا، ثُمَّ أُوتِينَا الْقُرْآنَ فَعَمِلْنَا إِلَىٰ غُرُوبِ الشَّمْسِ فَأُعْطِينَا قِيرَاطَيْنِ قِيرَاطَيْنِ، فَقَالَ أَهْلُ الْكِتَابَيْنِ: أَيْ رَبَّنَا! أَعْطَيْتَ هٰؤُلَاءِ قِيرَاطَيْنِ قِيرَاطَيْنِ وَأَعْطَيْتَنَا قِيرَاطًا قِيرَاطًا، وَنَحْنُ كُنَّا أَكْثَرَ عَمَلًا، قَالَ اللهُ: هَلْ ظَلَمْتُكُمْ مِنْ أَجْرِكُمْ مِنْ شَيْءٍ؟ قَالُوا: لَا، قَالَ: فَهُوَ فَضْلِي أُوتِيهِ مَنْ أَشَاءُ\n’’تم سے پہلی امتوں کے مقابلے میں تمھارے لیے باقی ماندہ وقت اتنا ہی ہے جتنا نمازِ عصر سے لے کر غروبِ آفتاب تک کا درمیانی وقت ہے۔ اہلِ تورات کو تورات دی گئی، انھوں نے اس پر عمل شروع کیا۔ جب آدھا دن گزر گیا تو وہ عاجز آ گئے۔ انھیں ایک ایک قیراط اجرت دے دی گئی۔ پھر اہلِ انجیل کو انجیل ملی، انھوں نے نصف النہار سے عصر تک عمل کیا، پھر وہ بھی عاجز آ گئے۔ انھیں ایک ایک قیراط اجرت دے دی گئی۔ پھر ہمیں قرآن مجید عطا کیا گیا۔ ہم نے غروبِ آفتاب تک عمل کیا۔ ہمیں دو دو قیراط اجرت دی گئی۔ اہلِ تورات و انجیل کہنے لگے: اے ہمارے پروردگار! تو نے ان لوگوں کو دو دو قیراط دیے اور ہمیں ایک ایک قیراط دیا، حالانکہ ہم نے زیادہ کام کیا ہے۔ اللہ تعالیٰ نے فرمایا: ’کیا میں نے تمھیں اجرت دینے میں کوئی ظلم کیا ہے؟‘ وہ کہنے لگے: ’نہیں!‘ اللہ تعالیٰ نے فرمایا: ’یہ میرا فضل ہے، میں جسے چاہتا ہوں عطا کرتا ہوں۔‘(1)\n§انجیل کی چھٹی پیش گوئی\n’’اُن دنوں میں یوحنا بپتسمہ دینے والا آیا اور یہودیہ کے بیابان میں یہ منادی کرنے لگا کہ توبہ کرو کیونکہ آسمان کی بادشاہی نزدیک آ گئی ہے۔ ...... پس جو درخت اچھا پھل نہیں لاتا وہ کاٹا اور آگ میں ڈالا جاتا ہے۔ میں تو تم کو توبہ کے لیے پانی سے بپتسمہ دیتا ہوں لیکن جو میرے بعد آتا ہے وہ مجھ سے زور آور ہے۔ میں اُس کی جوتیاں اٹھانے کے لائق نہیں۔ وہ تم کو روح القدس اور آگ سے بپتسمہ دے گا۔ اُس کا چھاج اُس کے ہاتھ میں ہے اور وہ اپنے کھلیان کو خوب صاف کرے گا اور اپنے گیہوں کو تو کھتے میں جمع کرے گا مگر بھوسی کو اُس آگ میں جلائے گا جو بجھنے کی نہیں۔‘‘(2)","",{"v":200480,"fn":"(1) صحیح البخاری: 557\n(2) کتاب مقدس (متی) 3:1-12"}],[958,"یوحنا اصطباغی (John the Baptist) (یحییٰ علیہ السلام) کے باپ زکریا (علیہ السلام) کاہنوں کے خاندان سے تھے۔ ان کی ماں ہارون (علیہ السلام) کے خاندان سے تھی۔ وہ اپنے پیروکاروں کو پانی کا جو بپتسمہ (اصطباغ) دیتے تھے، وہ گناہ سے علیحدگی اور صفائی کو ظاہر کرتا تھا۔ انھوں نے یسوع مسیح کی خواہش پر ان کو بھی بپتسمہ دیا۔ انھوں نے اپنے شاگردوں کو دعائیں سکھائیں اور اکثر روزے رکھنے کو کہا۔ یوحنا اصطباغی مسیح (علیہ السلام) کی پیدائش سے چھ ماہ پہلے جنوبی یہودیہ میں پیدا ہوئے۔ 26ء یا 27ء کا واقعہ ہے جب یوحنا نے اپنی خدمت (نبوت) یہودیہ اور یردن (اردن) کی وادی سے شروع کی۔ مسیح یسوع (علیہ السلام) نے اپنی تبلیغی خدمت (تبلیغ) یوحنا کے قید میں ڈالے جانے کے بعد شروع کی۔ اناجیل یوحنا (یحییٰ علیہ السلام) کی موت کا سبب ہیرودیاس (ہیرودیس اعظم کی بدکار پوتی) کی کینہ وری بتاتی ہیں کیونکہ وہ ہیرودیس انتیپاس کی غیر منکوحہ بیوی تھی اور یوحنا (علیہ السلام) نے اس کی مذمت کی تھی۔ یوحنا اصطباغی کے قتل کے بعد ان کے شاگردوں نے احترام سے انھیں دفن کیا حتیٰ کہ 20 سال بعد بھی افس میں ان کے شاگرد پائے جاتے تھے جن میں اپلوس جیسا یہودی عالم بھی شامل تھا۔(1) حضرت یحییٰ علیہ السلام کے متعلق مزید معلومات اطلس القرآن اردو (ص: 199 تا 203) میں ملاحظہ کیجیے۔\n۱ ’’جو درخت اچھا پھل نہیں لاتا وہ کاٹا اور آگ میں ڈالا جاتا ہے‘‘: انجیل کی تصریح کے مطابق اچھا پھل نہ لانے والا درخت کاٹ دیا جاتا ہے، چنانچہ یہودی اپنی نافرمانیوں اور بداعمالیوں کی وجہ سے اللہ کے غیظ و غضب کا شکار ہوئے۔ وہ حق کو جھٹلانے کی وجہ سے اللہ کی رحمت و برکت سے محروم ہو گئے تھے، لہٰذا آسمان کی بادشاہی، یعنی نبوت بنو اسماعیل کو دے دی گئی۔\n۲ ’’وہ اپنے کھلیان کو خوب صاف کرے گا‘‘: آخری نبی حضور محمد صلی اللہ علیہ وسلم نے عرب کے جاہلی معاشرے کی تربیت اور تزکیہ کر کے اسے دنیا کی امامت کے لیے تیار کر دیا۔ ارشادِ باری تعالیٰ ہے:\n﴿هُوَ الَّذِي بَعَثَ فِي الْأُمِّيِّينَ رَسُولًا مِنْهُمْ يَتْلُو عَلَيْهِمْ آيَاتِهِ وَيُزَكِّيهِمْ وَيُعَلِّمُهُمُ الْكِتَابَ وَالْحِكْمَةَ وَإِنْ كَانُوا مِنْ قَبْلُ لَفِي ضَلَالٍ مُبِينٍ﴾\n’’وہی ہے جس نے ان پڑھوں میں انھی میں سے ایک رسول بھیجا۔ وہ اس کی آیات انھیں پڑھ کر سناتا ہے اور ان کا تزکیہ کرتا ہے اور انھیں کتاب و حکمت کی تعلیم دیتا ہے اور اس سے پہلے تو وہ کھلی گمراہی میں پڑے ہوئے تھے۔‘‘(2)","",{"v":200481,"fn":"(1) قاموس الکتاب، ص: 1161,1162\n(2) الجمعة 62:2"}],[959,"رسول اللہ صلی اللہ علیہ وسلم نے جس طرح ’’گیہوں‘‘ کو ’’بھوسے‘‘ سے الگ اور حق کو باطل سے علیحدہ کر کے اس کے غلبے کی بنیاد رکھی، اس کی انسانی معاشروں میں کوئی مثال نہیں ملتی اور یہ ایسی حقیقت ہے جس کا مشرق و مغرب کے بڑے بڑے اہلِ علم نے اعتراف کیا ہے۔ ایک ہندو شاعر نبی صلی اللہ علیہ وسلم کی شان میں کہتا ہے:\n§خود نہ تھے جو راہ پر اوروں کے ہادی بن گئے\n§کیا نظر تھی جس نے مُردوں کو مسیحا کر دیا\n§انجیل کی ساتویں پیش گوئی\nمتی کی انجیل میں ’’آسمان کی بادشاہی‘‘ کو چھپے خزانے اور ایک نیا بیش قیمت موتی ملنے سے تشبیہ دی گئی ہے:\n’’آسمان کی بادشاہی کھیت میں چھپے خزانہ کی مانند ہے جسے کسی آدمی نے پا کر چھپا دیا اور خوشی کے مارے جا کر جو کچھ اُس کا تھا بیچ ڈالا اور اُس کھیت کو مول لے لیا۔ پھر آسمان کی بادشاہی اس سوداگر کی مانند ہے جو عمدہ موتیوں کی تلاش میں تھا۔ جب اُسے ایک بیش قیمت موتی ملا تو اُس نے جا کر جو کچھ اُس کا تھا سب بیچ ڈالا اور اُسے مول لے لیا۔‘‘(1)\n۱ ’’بیش قیمت موتی ملا تو اسے مول لے لیا‘‘: چھپا خزانہ اور نیا بیش قیمت موتی ملنے سے پہلی شریعتوں کی تنسیخ اور نئی شریعت کے نفاذ کا اشارہ ملتا ہے اور یہ شرف صرف اسلام اور شریعتِ محمدی ہی کو حاصل ہے۔ نبی کریم صلی اللہ علیہ وسلم کے ذریعے سے دین کی تکمیل ہو گئی اور پرانی شریعتوں کی جو باتیں اور حکمتیں اللہ تعالیٰ کو باقی رکھنا تھیں، وہ اس شریعت میں شامل کر دی گئیں۔ اللہ تعالیٰ فرماتا ہے:\n﴿وَأَنْزَلْنَا إِلَيْكَ الْكِتَابَ بِالْحَقِّ مُصَدِّقًا لِمَا بَيْنَ يَدَيْهِ مِنَ الْكِتَابِ وَمُهَيْمِنًا عَلَيْهِ﴾\n’’اور (اے نبی!) ہم نے آپ پر یہ کتاب حق کے ساتھ نازل کی، یہ تصدیق کرنے والی ہے اس کتاب کی جو اس سے پہلے تھی اور اس پر نگہبان ہے۔‘‘(2)\n﴿الْيَوْمَ أَكْمَلْتُ لَكُمْ دِينَكُمْ وَأَتْمَمْتُ عَلَيْكُمْ نِعْمَتِي وَرَضِيتُ لَكُمُ الْإِسْلَامَ دِينًا﴾\n’’آج میں نے تمھارے لیے تمھارا دین کامل کر دیا ہے اور تم پر اپنی نعمت پوری کر دی اور تمھارے لیے اسلام کو دین کی حیثیت سے پسند کر لیا۔‘‘(3)\nسیدنا عمر بن خطاب رضی اللہ عنہ سے ایک یہودی نے کہا:\n’’اے امیر المؤمنین! آپ کی کتاب (قرآن مجید) میں ایک ایسی آیت ہے جسے آپ پڑھتے رہتے ہیں۔","",{"v":200482,"fn":"(1) کتاب مقدس (متی) 13:44-46\n(2) المائدة 5:48\n(3) المائدة 5:3"}],[960,"اگر وہ آیت ہم یہودیوں کی جماعت پر نازل ہوتی تو ہم اس دن کو عید کا دن بنا لیتے۔‘‘\nسیدنا عمر رضی اللہ عنہ نے پوچھا: ’’وہ کون سی آیت ہے؟‘‘ یہودی نے کہا کہ یہ آیت:\n﴿الْيَوْمَ أَكْمَلْتُ لَكُمْ دِينَكُمْ وَأَتْمَمْتُ عَلَيْكُمْ نِعْمَتِي وَرَضِيتُ لَكُمُ الْإِسْلَامَ دِينًا﴾\nسیدنا عمر رضی اللہ عنہ نے کہا کہ ہم اس دن اور اس مقام کو جانتے ہیں جس میں یہ آیت نبی اکرم صلی اللہ علیہ وسلم پر نازل ہوئی۔ یہ آیت جمعے کے دن اُس وقت اتری جب آپ صلی اللہ علیہ وسلم عرفات میں کھڑے تھے۔(1)\nبائبل کی رو سے عیسیٰ علیہ السلام اس پیش گوئی کے مصداق نہیں کیونکہ اُن کی شریعت پہلی شریعتوں کی ناسخ نہیں تھی جیسا کہ یسوع (علیہ السلام) نے فرمایا ہے:\n’’یہ نہ سمجھو کہ میں توریت یا نبیوں کی کتابوں کو منسوخ کرنے آیا ہوں۔ منسوخ کرنے نہیں بلکہ پورا کرنے آیا ہوں۔‘‘(2)","",{"v":200483,"fn":"(1) صحیح البخاری: 45\n(2) کتاب مقدس (متی) 5:17"}],[961,"خاتم النبیین صلی اللہ علیہ وسلم کی بعثت و صداقت قرآن مجید میں اللہ تعالیٰ نے فرمایا:\n﴿وَإِذْ أَخَذَ اللهُ مِيثَاقَ النَّبِيِّينَ لَمَا آتَيْتُكُمْ مِنْ كِتَابٍ وَحِكْمَةٍ ثُمَّ جَاءَكُمْ رَسُولٌ مُصَدِّقٌ لِمَا مَعَكُمْ لَتُؤْمِنُنَّ بِهِ وَلَتَنْصُرُنَّهُ قَالَ أَأَقْرَرْتُمْ وَأَخَذْتُمْ عَلَىٰ ذٰلِكُمْ إِصْرِي قَالُوا أَقْرَرْنَا قَالَ فَاشْهَدُوا وَأَنَا مَعَكُمْ مِنَ الشَّاهِدِينَ﴾\nاور (یاد کرو) جب اللہ نے تمام نبیوں سے عہد لیا تھا کہ جب میں تمھیں کتاب اور حکمت عطا کروں، پھر تمھارے پاس کوئی رسول آئے جو اس (کتاب) کی تصدیق کرتا ہو جو تمھارے پاس ہے تو تمھیں اس پر ایمان لانا ہو گا اور اس کی مدد کرنی ہو گی۔ اللہ نے فرمایا: کیا تم اقرار کرتے ہو اور اس پر میرا عہد قبول کرتے ہو؟ انھوں نے کہا: ہم نے اقرار کیا۔ اللہ نے فرمایا: تو تم گواہ رہنا اور میں بھی تمھارے ساتھ گواہ ہوں۔‘‘\n(آل عمران 3:81)","",{"v":200484}],[962,"خاتم النبیین صلی اللہ علیہ وسلم کی بعثت و صداقت قرآن کی مذکورہ آیت کی صداقت بائبل سے ہوتی ہے:\nوَيُرْسِلَ يَسُوعَ الْمَسِيحَ الْمُبَشَّرَ بِهِ لَكُمْ قَبْلُ الَّذِي يَنْبَغِي أَنْ السَّمَاءَ تَقْبَلَهُ إِلَىٰ أَزْمِنَةِ رَدِّ كُلِّ شَيْءٍ الَّتِي تَكَلَّمَ عَنْهَا اللهُ بِفَمِ جَمِيعِ أَنْبِيَائِهِ الْقِدِّيسِينَ مُنْذُ الدَّهْرِ\n’’اور وہ اُس مسیح کو جو تمھارے واسطے مقرر ہوا ہے یعنی یسوع کو بھیجے۔ ضرور ہے کہ وہ آسمان میں اُس وقت تک رہے جب تک کہ وہ سب چیزیں بحال نہ کی جائیں جن کا ذکر خدا نے اپنے پاک نبیوں کی زبانی کیا ہے جو دنیا کے شروع سے ہوتے آئے ہیں۔‘‘\nکتاب مقدس (اعمال) 3:20,21","",{"v":200485}],[963,"§پطرس کی بشارت\nعہد نامہ جدید میں مسیحی جماعتوں کے نام پطرس کے دو خطوط شامل ہیں۔ پطرس (Peter) حواری اندریاس کا بھائی اور مسیح (علیہ السلام) کا سب سے مشہور شاگرد تھا۔ اس کا اصل نام شمعون تھا۔ وہ بیت صیدا نزدِ گلیل کا ماہی گیر تھا۔ اس کے باپ کا نام یوحنا (غالباً یوناہ کا مخفف) تھا۔ مسیح (علیہ السلام) نے اس کا نام کیفا (بمعنی ’’پتھر‘‘) رکھا جبکہ انجیل نویس یوحنا نے آرامی لفظ ’’کیفا‘‘ کا ترجمہ یونانی میں پطرس (Petros) کیا۔ اس سے پہلے پطرس اپنے بھائی اندریاس کی طرح یوحنا اصطباغی کی منادی سن کر اس کا شاگرد بن گیا تھا۔ 44ء میں جب اگرپا اول نے کلیسیا (مسیحی برادری) کو ستانا شروع کیا تو پطرس قید سے معجزانہ رہائی پا کر بچ گیا۔ اس نے اپنی بیوی کے ساتھ یہودیوں میں منادی (تبلیغ) کرنے کے لیے بہت سفر کیا۔ آخر کار وہ رومہ گیا اور وہیں نیرو کے عہد میں اسے شہید کر دیا گیا۔(1)\n[تصویر: کتاب پطرس (عہد نامہ جدید)]\nپطرس نے لوگوں سے خطاب کرتے ہوئے کہا:\n’’پس توبہ کرو اور رجوع لاؤ تاکہ تمھارے گناہ مٹائے جائیں اور اس طرح خداوند کے حضور سے تازگی کے دن آئیں۔ اور وہ اُس مسیح کو جو تمھارے واسطے مقرر ہوا ہے یعنی یسوع کو بھیجے۔ ضرور ہے کہ وہ آسمان میں اُس وقت تک رہے جب تک کہ وہ سب چیزیں بحال نہ کی جائیں جن کا ذکر خدا نے اپنے پاک نبیوں کی زبانی کیا ہے جو دنیا کے شروع سے ہوتے آئے ہیں۔ چنانچہ موسیٰ نے کہا کہ خداوند خدا تمھارے بھائیوں میں سے تمھارے لیے مجھ سا ایک نبی پیدا کرے گا۔ جو کچھ وہ تم سے کہے اُس کی سننا۔ اور یوں ہو گا کہ جو شخص اُس نبی کی نہ سنے گا وہ اُمت میں سے نیست و نابود کر دیا جائے گا۔ بلکہ","",{"v":200486,"fn":"(1) قاموس الکتاب، ص: 190-193","im":["v2_p486.jpg"]}],[964,"سموئیل سے لے کر پچھلوں تک جتنے نبیوں نے کلام کیا اُن سب نے ان دنوں کی خبر دی ہے۔ تم نبیوں کی اولاد اور اُس عہد کے شریک ہو جو خدا نے تمھارے باپ دادا سے باندھا جب ابراہم سے کہا کہ تیری اولاد سے دنیا کے سب گھرانے برکت پائیں گے۔(1)\n§پطرس کے خطاب سے ماخوذ امور\nپطرس کے مندرجہ بالا خطاب میں چند امور کی طرف اشارہ ہے:\n(ا) یہ پیش گوئی یسوع (عیسیٰ علیہ السلام) کے سوا کسی اور نبی کے لیے ہے۔ اُس نبی کے ظہور کے وقت تک عیسیٰ علیہ السلام آسمان میں قیام پذیر رہیں گے۔\n(ب) اس کا تعلق بنی اسرائیل سے نہیں بلکہ اُن کے بھائیوں بنی اسماعیل سے ہوگا۔\n(ج) اُس نبی اور موسیٰ علیہ السلام میں بہت سی باتوں میں مشابہت ہوگی۔ یہ ساری باتیں جو تورات کی پہلی پیش گوئی میں گزر چکی ہیں، صرف نبی کریم صلی اللہ علیہ وسلم ہی کی ذاتِ بابرکات میں پائی جاتی ہیں۔\n(د) ’’جو شخص اُس نبی کی نہ سنے گا وہ اُمت میں سے نیست و نابود کر دیا جائے گا۔‘‘\nرسول اللہ صلی اللہ علیہ وسلم نے بھی یہی بات فرمائی ہے:\nوَالَّذِي نَفْسُ مُحَمَّدٍ بِيَدِهِ! لَا يَسْمَعُ بِي أَحَدٌ مِنْ هٰذِهِ الْأُمَّةِ يَهُودِيٌّ وَلَا نَصْرَانِيٌّ، ثُمَّ يَمُوتُ وَلَمْ يُؤْمِنْ بِالَّذِي أُرْسِلْتُ بِهِ، إِلَّا كَانَ مِنْ أَصْحَابِ النَّارِ\n’’اس ذات کی قسم جس کے قبضے میں محمد کی جان ہے! اس امت کا کوئی بھی یہودی یا عیسائی فرد میرے بارے میں سنتا ہے، پھر جو کچھ مجھے دے کر مبعوث کیا گیا ہے، اُس پر ایمان لائے بغیر مر جاتا ہے تو وہ جہنمیوں میں سے ہوگا۔‘‘(2)\nگویا فرمانِ نبوی یہ ہے کہ جو لوگ اس وقت میرے زمانے میں موجود ہیں یا قیامت تک اس دنیا میں آئیں گے، ان سب کے لیے مجھ پر ایمان لانا اور میری اطاعت و فرماں برداری اختیار کرنا واجب ہے۔ یہود و نصاریٰ کا بطورِ خاص اس لیے ذکر کیا کہ وہ اہلِ کتاب ہیں۔ اگر ان کے لیے ایمان لانا اور اللہ اور اس کے رسول صلی اللہ علیہ وسلم کی اطاعت و فرماں برداری اختیار کرنا واجب ہے تو دوسروں کے لیے یہ بالاولیٰ واجب ہوگا اور جو شخص ایسا نہیں کرے گا، وہ","",{"v":200487,"fn":"(1) کتاب مقدس (اعمال) 3:19-25\n(2) صحیح مسلم: 153"}],[965,"بلا شبہ جہنم رسید ہو گا۔\n(۲) اس پیش گوئی کے مطابق سموئیل (شموئیل علیہ السلام) سے لے کر پچھلوں تک تمام نبیوں نے آنے والے نبی کی خبر دی تھی۔\nاس پیش گوئی کے مصداق نبی کریم حضور محمد صلی اللہ علیہ وسلم ہی ہیں جن کی آمد کی پیش گوئی حضرت موسیٰ، حضرت شموئیل، حضرت عیسیٰ اور دیگر انبیاء علیہم السلام نے کی تھی۔","",{"v":200488}],[966,"§شجرہ طیبہ\n§محمد رسول اللہ صلی اللہ علیہ وسلم اور دیگر انبیائے کرام علیہم السلام\n[تصویر: شجرہ طیبہ — محمد رسول اللہ صلی اللہ علیہ وسلم اور دیگر انبیائے کرام]\nآدم علیہ السلام، ادریس علیہ السلام، نوح علیہ السلام، سام، حام، یافث، صالح علیہ السلام، ہود علیہ السلام، شعیب علیہ السلام، ابراہیم علیہ السلام، اسماعیل علیہ السلام، اسحاق علیہ السلام، لوط علیہ السلام، یعقوب علیہ السلام، یوسف علیہ السلام، ایوب علیہ السلام، ذوالکفل علیہ السلام، موسیٰ علیہ السلام، ہارون علیہ السلام، عمران، الیاس علیہ السلام، الیسع علیہ السلام، یونس علیہ السلام، داؤد علیہ السلام، سلیمان علیہ السلام، زکریا علیہ السلام، یحییٰ علیہ السلام، عیسیٰ علیہ السلام، خاتم النبیین محمد رسول اللہ صلی اللہ علیہ وسلم\nقبائلِ بنی اسرائیل: روبن، شمعون، یہودا، لاوی، آشر، زبولون، دان، نفتالی، جاد، اشکار، بنیامین\nرسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’تمام لوگ آدم سے پیدا کیے گئے اور آدم مٹی سے پیدا ہوئے تھے۔‘‘","",{"v":200489,"im":["v2_p489.jpg"]}],[967,"خاتم النبیین صلی اللہ علیہ وسلم کی بعثت و صداقت قرآن مجید میں اللہ تعالیٰ نے فرمایا:\n﴿فَإِنْ جَاءُوكَ فَاحْكُمْ بَيْنَهُمْ أَوْ أَعْرِضْ عَنْهُمْ وَإِنْ تُعْرِضْ عَنْهُمْ فَلَنْ يَضُرُّوكَ شَيْئًا وَإِنْ حَكَمْتَ فَاحْكُمْ بَيْنَهُمْ بِالْقِسْطِ﴾\n’’پھر اگر وہ آپ کے پاس آئیں تو آپ (کو اختیار ہے کہ) ان کے درمیان فیصلہ کر دیں یا ان سے اعراض کریں اور اگر آپ ان سے منہ موڑ لیں گے تب بھی وہ آپ کو قطعاً کوئی نقصان نہیں پہنچا سکیں گے۔ اور اگر آپ ان کے مابین کوئی فیصلہ کریں تو انصاف کے ساتھ کریں۔‘‘\n(المائدة 5:42)","",{"v":200490}],[968,"خاتم النبیین صلی اللہ علیہ وسلم کی بعثت و صداقت قرآن کی مذکورہ آیت کی صداقت بائبل سے ہوتی ہے:\nثُمَّ رَأَيْتُ السَّمَاءَ مَفْتُوحَةً وَإِذَا فَرَسٌ أَبْيَضُ وَالْجَالِسُ عَلَيْهِ يُدْعَىٰ أَمِينًا وَصَادِقًا وَبِالْعَدْلِ يَحْكُمُ وَيُحَارِبُ\n’’پھر میں نے آسمان کو کھلا ہوا دیکھا اور کیا دیکھتا ہوں کہ ایک سفید گھوڑا ہے اور اس پر ایک سوار ہے جو سچا اور برحق کہلاتا ہے اور وہ راستی کے ساتھ انصاف کرتا ہے۔‘‘\nکتاب مقدس (مکاشفہ یوحنا) 19:11","",{"v":200491}],[969,"مکاشفہ یوحنا کی بشارات\n§یوحنا کی پہلی پیش گوئی\nعہد نامہ جدید کی آخری کتاب میں لکھا ہے کہ یوحنا عارف نے بتایا:\n’’پھر میں نے آسمان کو کھلا ہوا دیکھا اور کیا دیکھتا ہوں کہ ایک سفید گھوڑا ہے اور اُس پر ایک سوار ہے جو سچا اور برحق کہلاتا ہے اور وہ راستی کے ساتھ انصاف اور لڑائی کرتا ہے۔ اور اُس کی آنکھیں آگ کے شعلے ہیں اور اُس کے سر پر بہت سے تاج ہیں اور اُس کا ایک نام لکھا ہوا ہے جسے اُس کے سوا اور کوئی نہیں جانتا۔ اور وہ خون کی چھڑکی ہوئی پوشاک پہنے ہوئے ہے اور اُس کا نام کلامِ خدا کہلاتا ہے۔ اور آسمان کی فوجیں سفید گھوڑوں پر سوار اور سفید اور صاف مہین کتانی کپڑے پہنے ہوئے اُس کے پیچھے پیچھے ہیں۔ اور قوموں کے مارنے کے لیے اُس کے منہ سے ایک تیز تلوار نکلتی ہے اور وہ لوہے کے عصا سے اُن پر حکومت کرے گا۔‘‘(1)\n[تصویر: کتاب یوحنا (عہد نامہ جدید)]\nبائبل کے شارحین کا خیال ہے کہ یوحنا عارف کا متذکرہ بالا مکاشفہ یسوع علیہ السلام کے لیے ہے۔ لیکن یسوع علیہ السلام اس کی ایک شق پر بھی پورے نہیں اترتے۔ یہ خواب یقیناً کئی وجوہ کی بنا پر پیغمبرِ آخر الزمان محمد صلی اللہ علیہ وسلم ہی کے بارے میں ہے۔\n۱ ’’جو سچا اور برحق کہلاتا ہے‘‘: رسول اللہ صلی اللہ علیہ وسلم نبوت سے پہلے بھی صادق و امین کے لقب سے معروف تھے اور نبوت کے بعد بھی یہ القاب آپ کے لیے مستعمل رہے۔\n۲ ’’وہ راستی کے ساتھ انصاف اور لڑائی کرتا ہے‘‘: نبی کریم صلی اللہ علیہ وسلم کا انصاف اتنا دوٹوک، بے لاگ، معروف اور","",{"v":200492,"fn":"(1) کتاب مقدس (یوحنا عارف کا مکاشفہ) 19:11-15","im":["v2_p492.jpg"]}],[970,"مسلمہ تھا کہ مسلمانوں کے بدترین دشمن یہودی بھی اپنے فیصلے رسول اللہ صلی اللہ علیہ وسلم سے کرایا کرتے تھے۔ سچائی اور عدل آپ صلی اللہ علیہ وسلم کی شخصیت کی پہچان تھی۔ آپ نے انھی اوصاف کی تعلیم دی۔ اللہ تعالیٰ فرماتا ہے:\n﴿فَإِنْ جَاءُوكَ فَاحْكُمْ بَيْنَهُمْ أَوْ أَعْرِضْ عَنْهُمْ ۖ وَإِنْ تُعْرِضْ عَنْهُمْ فَلَنْ يَضُرُّوكَ شَيْئًا ۖ وَإِنْ حَكَمْتَ فَاحْكُمْ بَيْنَهُمْ بِالْقِسْطِ﴾(1)\n’’پھر اگر وہ آپ کے پاس آئیں تو آپ (کو اختیار ہے کہ) ان کے مابین فیصلہ کر دیں یا ان سے اعراض کریں اور اگر آپ ان سے منہ موڑ لیں گے تب بھی وہ آپ کو قطعاً کوئی نقصان نہیں پہنچا سکیں گے۔ اور اگر آپ ان کے مابین کوئی فیصلہ کریں تو انصاف کے ساتھ کریں۔‘‘\nمزید فرمایا:\n﴿إِنَّ اللهَ يَأْمُرُكُمْ أَنْ تُؤَدُّوا الْأَمَانَاتِ إِلَىٰ أَهْلِهَا وَإِذَا حَكَمْتُمْ بَيْنَ النَّاسِ أَنْ تَحْكُمُوا بِالْعَدْلِ﴾\n’’بے شک اللہ تمھیں حکم دیتا ہے کہ تم امانتیں ان کے حقداروں کو واپس کر دو۔ اور جب تم لوگوں کے مابین فیصلہ کرو تو انصاف کے ساتھ فیصلہ کرو۔‘‘(2)\n§دشمنوں سے برتاؤ کی اسلامی اقدار\nنبی کریم صلی اللہ علیہ وسلم کے جہادی معرکوں میں بھی رحم و کرم اور انتہائی عدل کی شان ہوتی تھی۔ سیدنا شداد بن اوس رضی اللہ عنہ رسول اللہ صلی اللہ علیہ وسلم سے روایت کرتے ہیں، آپ صلی اللہ علیہ وسلم نے فرمایا:\nإِنَّ اللهَ كَتَبَ الْإِحْسَانَ عَلَىٰ كُلِّ شَيْءٍ، فَإِذَا قَتَلْتُمْ فَأَحْسِنُوا الْقِتْلَةَ وَإِذَا ذَبَحْتُمْ فَأَحْسِنُوا الذَّبْحَ\n’’بے شک اللہ تعالیٰ نے ہر شے پر احسان لکھ دیا ہے۔ جب تم قتل کرو تو اچھے طریقے سے قتل کرو اور جب تم ذبح کرو تو اچھے طریقے سے ذبح کرو۔‘‘(3)\nسیدنا عبداللہ بن عمر رضی اللہ عنہما بیان کرتے ہیں کہ ایک غزوے میں رسول اللہ صلی اللہ علیہ وسلم نے کسی عورت کی لاش دیکھی تو آپ صلی اللہ علیہ وسلم نے سخت ناپسندیدگی کا اظہار کیا اور جنگ میں عورتوں اور بچوں کو قتل کرنے سے منع فرما دیا۔(4)\nسیدنا بریدہ رضی اللہ عنہ بیان فرماتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم جب کسی کو کسی لشکر یا سریے کا امیر بناتے تو اسے بالخصوص اپنی ذات کے بارے میں اللہ کا تقویٰ اختیار کرنے اور اپنے ساتھیوں کے بارے میں بھلائی اور خیر خواہی کی","",{"v":200493,"fn":"(1) المائدة 5:42\n(2) النساء 4:58\n(3) صحیح مسلم: 1955\n(4) صحیح البخاری: 3014,3015"}],[971,"وصیت کرتے، پھر فرماتے:\n﴿اغْزُوا بِاسْمِ اللهِ فِي سَبِيلِ اللهِ، قَاتِلُوا مَنْ كَفَرَ بِاللهِ، اغْزُوا فَلَا تَغُلُّوا وَلَا تَغْدِرُوا وَلَا تُمَثِّلُوا وَلَا تَقْتُلُوا وَلِيدًا﴾\n’’اللہ کے نام سے اللہ کی راہ میں نکلو۔ ان سے لڑو جنھوں نے اللہ کا انکار کیا۔ جہاد کرو، (مال غنیمت میں) خیانت نہ کرو، دھوکہ نہ دو، لاشوں کا مثلہ نہ کرو اور کسی بچے کو قتل مت کرو۔‘‘(1)\nنبی کریم صلی اللہ علیہ وسلم معاہدوں کی سختی سے پابندی کرتے تھے۔ اللہ تعالیٰ نے بھی معاہدے پورے کرنے کا حکم دیا ہے۔ اللہ تعالیٰ فرماتا ہے:\n﴿يَا أَيُّهَا الَّذِينَ آمَنُوا أَوْفُوا بِالْعُقُودِ﴾\n’’اے لوگو جو ایمان لائے ہو! معاہدے پورے کیا کرو۔‘‘(2)\nاسی طرح مسلمانوں کو معاہدہ امن کی پابندی کا بھی حکم دیا گیا:\n﴿فَمَا اسْتَقَامُوا لَكُمْ فَاسْتَقِيمُوا لَهُمْ﴾\n’’پس جب تک وہ تمھارے ساتھ سیدھے رہیں، تم بھی ان کے ساتھ سیدھے رہو۔‘‘(3)\nمسلمانوں کو دشمنوں کے معاملے میں بھی یہ تعلیم دی گئی ہے کہ ان سے جتنی تکلیف پہنچی ہو، اس سے زیادہ بدلہ لینے کی اجازت نہیں:\n﴿وَإِنْ عَاقَبْتُمْ فَعَاقِبُوا بِمِثْلِ مَا عُوقِبْتُمْ بِهِ ۖ وَلَئِنْ صَبَرْتُمْ لَهُوَ خَيْرٌ لِلصَّابِرِينَ﴾\n’’اور اگر تم بدلہ لو تو اتنا ہی بدلہ لو جتنی تمھیں تکلیف دی گئی ہو اور اگر تم صبر کرو تو وہ صابرین کے لیے بہت بہتر ہے۔‘‘(4)\nعین لڑائی کی حالت میں بھی اس سے بڑھ کر راستبازی کی راہ اور کیا ہو سکتی ہے؟\n3 ’’اور اُس کی آنکھیں آگ کے شعلے ہیں:‘‘ نبی کریم صلی اللہ علیہ وسلم کی آنکھوں میں سرخی تھی اور یہ سرخی ہمیشہ برقرار رہتی تھی۔(5) اس کی تائید ابن اسحاق کی اس روایت سے بھی ہوتی ہے کہ رسول اللہ صلی اللہ علیہ وسلم شام کے شہر بصرٰی پہنچ کر مقامی بازار میں واقع ایک راہب کے گرجے کے پاس درخت کے سائے میں تشریف فرما ہوئے۔ اس راہب کا نام نسطورا یا بعض روایات کے مطابق نسطور تھا۔ نسطورا کی سیدہ خدیجہ کے غلام میسرہ سے پہلے ہی جان پہچان تھی۔","",{"v":200494,"fn":"(1) صحیح مسلم: 1731\n(2) المائدة 5:1\n(3) التوبة 9:7\n(4) النحل 16:126\n(5) مسند أحمد: 89/1"}],[972,"یہ راہب محمد صلی اللہ علیہ وسلم کو دیکھ کر چونک پڑا۔ اُس نے پوچھا: ’’میسرہ! اس درخت کے نیچے جو صاحب تشریف فرما ہیں، وہ کون ہیں؟‘‘ میسرہ نے جواب دیا: ’’یہ صاحب قریش کے ایک فرد اور اہل حرم سے ہیں۔‘‘\nنسطورا کہنے لگا: ’’اس درخت کے نیچے تو نبی کے سوا کبھی کوئی فرد نہیں ٹھہرا۔‘‘ پھر پوچھنے لگا: ’’کیا ان کی آنکھوں میں سرخ ڈورے ہیں؟‘‘ میسرہ بولا: ’’جی ہاں! سرخ ڈورے تو ان کی آنکھوں میں ہر وقت جلوہ نما رہتے ہیں۔‘‘ نسطورا کہنے لگا: ’’یہ وہی ہیں، یہ اس امت کے آخری نبی ہوں گے۔‘‘(1)\n4 ’’اُس کے سر پر بہت سے تاج ہیں:‘‘ نبی کریم صلی اللہ علیہ وسلم کے پیروکاروں نے قیصر روم، کسرائے فارس اور دوسرے بہت سے بادشاہوں کو شکست دی۔ اُن کے تاج اور خزانے مسلمانوں کے قبضے میں آئے۔ دوسرے مجازی معنوں میں لیں تو نبی کریم صلی اللہ علیہ وسلم کے سر پر نبوت، عدالت اور حکومت کے کئی تاج جگمگا رہے تھے۔\nقیصر روم کا مطلب ہے روم کا بادشاہ۔ قیصر دراصل سلطنت روم کے بادشاہوں کا لقب ہے۔ نبی کریم صلی اللہ علیہ وسلم کے ہم عصر قیصر کا نام ہرقل (Hercules) تھا۔ تاریخ میں یہ ہرقل اول (610-641ء) کہلایا۔ اس کا تعلق یونانی خاندان سے تھا، چنانچہ اس سے قسطنطنیہ (استنبول) میں یونانی بادشاہت کا دور شروع ہوا جسے عموماً بازنطینی سلطنت کہا جاتا ہے۔(2)\n5 ’’آسمان کی فوجیں سفید گھوڑوں پر سوار اس کے پیچھے پیچھے ہیں:‘‘ جنگ بدر اور دوسری کئی جنگوں میں نبی کریم صلی اللہ علیہ وسلم کی نصرت کے لیے آسمان سے فرشتے اترتے رہے۔ اس کے بارے میں اللہ تعالیٰ کا فرمان ہے:\n﴿إِذْ تَسْتَغِيثُونَ رَبَّكُمْ فَاسْتَجَابَ لَكُمْ أَنِّي مُمِدُّكُمْ بِأَلْفٍ مِنَ الْمَلَائِكَةِ مُرْدِفِينَ﴾\n’’(یاد کرو) جب تم اپنے رب سے فریاد کر رہے تھے تو اس نے تمھاری فریاد قبول کر لی (اور کہا) کہ بے شک میں ایک دوسرے کے پیچھے آنے والے ایک ہزار فرشتوں سے تمھاری مدد کروں گا۔‘‘(3)\nعلی بن ابی طلحہ نے سیدنا ابن عباس رضی اللہ عنہ سے روایت کیا ہے کہ اللہ تعالیٰ نے اپنے نبی اور مومنوں کی ایک ہزار فرشتوں کے ساتھ مدد فرمائی جن میں سے پانچ سو فرشتوں کی قیادت حضرت جبریل علیہ السلام کر رہے تھے اور پانچ سو کی قیادت حضرت میکائیل علیہ السلام کے پاس تھی۔(4)\nاسی طرح سیدنا عمر رضی اللہ عنہ سے مروی ایک روایت میں ہے کہ ایک مسلمان ایک مشرک کا تعاقب کر رہا تھا کہ اس","",{"v":200495,"fn":"(1) السيرة لابن إسحاق: 128,129/1، دلائل النبوة لأبي نعيم: 173/1\n(2) فتح الباري: 46/1، تاج العروس، مادة: قیصر، انسائیکلوپیڈیا تاریخ عالم: 173,174/12\n(3) الأنفال 8:9\n(4) تفسير الطبري: 259/9"}],[973,"[تصویر: میدان بدر]\nنے فضا میں اپنے اوپر کوڑے کی ضرب اور ایک شہوار کی آواز سنی، وہ اپنے گھوڑے سے کہہ رہا تھا: حَيْزُوم آگے بڑھو، پھر اچانک اس نے دیکھا کہ وہ مشرک چاروں شانے چت ہو کر گر پڑا، اس کی ناک اور اس کا چہرہ زخموں سے اس طرح چور چور تھا جیسے اس پر کوڑے برسائے گئے ہوں حتیٰ کہ اس کے سارے جسم کے ٹکڑے ٹکڑے ہو گئے۔ اس انصاری مسلمان نے یہ واقعہ رسول اللہ صلی اللہ علیہ وسلم کو سنایا تو آپ صلی اللہ علیہ وسلم نے فرمایا:\n﴿صَدَقْتَ، ذٰلِكَ مِنْ مَدَدِ السَّمَاءِ الثَّالِثَةِ﴾\n’’تم سچ کہتے ہو، یہ تیسرے آسمان سے مدد تھی۔‘‘(1)\nایک اور مقام پر فرمایا:\n﴿إِذْ تَقُولُ لِلْمُؤْمِنِينَ أَلَنْ يَكْفِيَكُمْ أَنْ يُمِدَّكُمْ رَبُّكُمْ بِثَلَاثَةِ آلَافٍ مِنَ الْمَلَائِكَةِ مُنْزَلِينَ ۝ بَلَىٰ إِنْ تَصْبِرُوا وَتَتَّقُوا وَيَأْتُوكُمْ مِنْ فَوْرِهِمْ هٰذَا يُمْدِدْكُمْ رَبُّكُمْ بِخَمْسَةِ آلَافٍ مِنَ الْمَلَائِكَةِ مُسَوِّمِينَ﴾","",{"v":200496,"fn":"(1) صحیح مسلم: 1763","im":["v2_p496.jpg"]}],[974,"(اے نبی!) جب آپ مومنوں سے کہہ رہے تھے: کیا تمھارے لیے کافی نہ ہوگا کہ تمھارا رب (آسمان سے) تین ہزار فرشتے اتار کر تمھاری مدد کرے؟ ہاں! اگر تم ثابت قدم رہو اور اللہ سے ڈرتے رہو اور دشمن تم پر آ دھمکے تو اسی لمحے تمھارا رب پانچ ہزار فرشتوں سے تمھاری مدد فرمائے گا جو اپنے خاص نشان لگائے ہوئے ہوں گے۔(1)\n§یوحنا کی دوسری پیش گوئی\nیوحنا عارف نے اپنے مکاشفے میں بتایا:\n’’جو غالب آئے اور جو میرے کاموں کے موافق آخر تک عمل کرے میں اُسے قوموں پر اختیار دوں گا۔ اور وہ لوہے کے عصا سے اُن پر حکومت کرے گا۔‘‘(2)\n1 ’’وہ لوہے کے عصا سے اُن پر حکومت کرے گا:‘‘ بائبل کے شارحین اس پیش گوئی کا مصداق عیسیٰ علیہ السلام کو قرار دیتے ہیں لیکن یہ بات محل نظر ہے۔ اس پیش گوئی میں ہے کہ وہ غالب آکر لوہے کے عصا سے اُن پر حکومت کرے گا جبکہ عیسیٰ علیہ السلام کے بارے میں بائبل میں مذکور ہے:\n’’یسوع نے جواب دیا کہ میری بادشاہی اس دنیا کی نہیں۔ اگر میری بادشاہی دنیا کی ہوتی تو میرے خادم لڑتے تاکہ میں یہودیوں کے حوالے نہ کیا جاتا۔ مگر اب میری بادشاہی یہاں کی نہیں۔‘‘(3)\nبلکہ یسوع تو اس سے بھاگتے پھرتے تھے:\n’’پس یسوع یہ معلوم کر کے کہ وہ آکر مجھے بادشاہ بنانے کے لیے پکڑا چاہتے ہیں پھر پہاڑ پر اکیلا چلا گیا۔‘‘(4)\nجبکہ اللہ تعالیٰ نے رسول اللہ صلی اللہ علیہ وسلم کے بارے میں فرمایا:\n﴿وَيَنْصُرَكَ اللهُ نَصْرًا عَزِيزًا﴾\n’’اور (تاکہ) اللہ آپ کی مدد کرے، زبردست مدد۔‘‘(5)\nنبی کریم صلی اللہ علیہ وسلم کو نبوت کے ساتھ ساتھ حکومت بھی عطا کی گئی۔ اللہ تعالیٰ کا ارشاد ہے:\n﴿فَلَا وَرَبِّكَ لَا يُؤْمِنُونَ حَتَّىٰ يُحَكِّمُوكَ فِيمَا شَجَرَ بَيْنَهُمْ ثُمَّ لَا يَجِدُوا فِي أَنْفُسِهِمْ حَرَجًا مِمَّا قَضَيْتَ وَيُسَلِّمُوا تَسْلِيمًا﴾","",{"v":200497,"fn":"(1) آل عمران 3:124,125\n(2) کتاب مقدس (مکاشفہ) 2:26,27\n(3) کتاب مقدس (یوحنا) 18:36\n(4) کتاب مقدس (یوحنا) 6:15\n(5) الفتح 48:3"}],[975,"چنانچہ (اے نبی!) آپ کے رب کی قسم! وہ مومن نہیں ہو سکتے جب تک اپنے باہمی اختلاف میں آپ کو فیصلہ کرنے والا نہ مان لیں، پھر آپ کے کیے ہوئے فیصلے پر ان کے دلوں میں کوئی تنگی نہ آنے پائے اور وہ اسے دل و جان سے مان لیں۔(1)\n[تصویر: جزیرہ نمائے عرب اور گرد و نواح کا نقشہ]\nنقشے کے اہم مقامات: ایشیا، فارس (ایران)، شام، دمشق، فلسطین، عراق، بصرہ، خلیج بصرہ (خلیج فارس)، خلیج عمان، عمان، نجد، حجاز، مدینہ منورہ، مکہ معظمہ، جزیرہ نمائے عرب، حضرموت، یمن، بحیرہ عرب، خلیج عدن، حبشہ، سودان، نوبیا، بحیرہ قلزم (احمر)\nرسول اللہ صلی اللہ علیہ وسلم کی حکومت نہایت مضبوط بنیادوں پر استوار تھی اور آپ کے دور میں جزیرہ نمائے عرب کے دس لاکھ مربع میل پر اسلامی حکومت قائم ہو چکی تھی۔ یوں مکاشفہ یوحنا کی یہ پیش گوئی آخری نبی حضور محمد صلی اللہ علیہ وسلم کی بعثت کے بارے میں ہے۔\n§یوحنا کی تیسری پیش گوئی\nیوحنا عارف نے اپنے مکاشفے میں بتایا:","",{"v":200498,"fn":"(1) النساء 4:65","im":["v2_p498.jpg"]}],[976,"’’پھر میں نے نگاہ کی تو کیا دیکھتا ہوں کہ وہ برّہ صیون کے پہاڑ پر کھڑا ہے اور اُس کے ساتھ ایک لاکھ چوالیس ہزار شخص ہیں جن کے ماتھے پر اُس کا اور اُس کے باپ کا نام لکھا ہوا ہے۔ اور مجھے آسمان سے ایک ایسی آواز سنائی دی جو زور کے پانی اور بڑی گرج کی سی آواز تھی اور جو آواز میں نے سنی وہ ایسی تھی جیسے بربط نواز بربط بجاتے ہوں۔ وہ تخت کے سامنے اور چاروں جانداروں اور بزرگوں کے آگے گویا ایک نیا گیت گا رہے تھے اور اُن ایک لاکھ چوالیس ہزار شخصوں کے سوا جو دنیا سے خرید لیے گئے تھے کوئی اُس گیت کو نہ سیکھ سکا۔ یہ وہ ہیں جو عورتوں کے ساتھ آلودہ نہیں ہوئے بلکہ کنوارے ہیں۔ یہ وہ ہیں جو برّہ کے پیچھے پیچھے چلتے ہیں، جہاں کہیں وہ جاتا ہے۔ یہ خدا اور برّہ کے لیے پہلے پھل ہونے کے واسطے آدمیوں میں سے خرید لیے گئے ہیں۔ اور اُن کے منہ سے کبھی جھوٹ نہ نکلا تھا۔ وہ بے عیب ہیں۔‘‘(1)\n1 ’’وہ برّہ صیون کے پہاڑ پر کھڑا ہے اور اُس کے ساتھ ایک لاکھ چوالیس ہزار شخص ہیں:‘‘ بائبل کے شارحین کہتے ہیں کہ یہ پیش گوئی عیسیٰ علیہ السلام کے لیے ہے اور برّہ سے مراد یسوع (عیسیٰ علیہ السلام) ہیں۔(2) لیکن اگر اس پیش گوئی کا جائزہ لیا جائے تو یسوع اس کی ایک بات پر بھی پورے نہیں اترتے۔\nمکاشفات کی اصطلاح میں برّہ سے مراد وہ برگزیدہ ہستی ہے جو رب کے بعد سب سے برتر ہو۔ بائبل کے شارحین کے نزدیک صیون (صہیون) سے مقدس پہاڑ یا مقام مراد ہوتا ہے۔ اس بشارت سے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ حجۃ الوداع کے موقع پر صحابہ کی کثیر تعداد کی طرف اشارہ ہے۔ نبی کریم صلی اللہ علیہ وسلم کے ساتھ حجۃ الوداع کے موقع پر ایک لاکھ سے زائد جاں نثار صحابہ موجود تھے جبکہ حضرت عیسیٰ علیہ السلام کو متبعین کی اتنی کثیر تعداد میسر نہ تھی، لہٰذا اس پیش گوئی سے مراد حضرت عیسیٰ علیہ السلام نہیں ہو سکتے، اس کا مصداق نبی آخر الزماں ہی ہیں جن کے کوہ فاران (مکہ مکرمہ) سے جلوہ گر ہونے کی خبر تورات کی کتاب استثنا (33:1,2) میں دی گئی تھی مگر تحریف کرنے والوں نے فاران کی جائے وقوع فلسطین میں جا پہنچائی اور یوحنا عارف کے مکاشفے میں کوہ فاران کے بجائے صہیون کا پہاڑ بنا دیا گیا۔ یاد رہے فاران مکہ مکرمہ ہی کے ایک پہاڑ کا نام ہے (جیسا کہ صحیفہ حبقوق کی بشارت کے ضمن میں بیان کیا جا چکا ہے) اور فتح مکہ کے دن دس ہزار قدسی صفت صحابہ کرام رضی اللہ عنہم رسول اللہ صلی اللہ علیہ وسلم کے ہمراہ تھے۔\n2 ’’جن کے ماتھے پر اُس کا اور اُس کے باپ کا نام لکھا ہوا ہے:‘‘ بائبل کی اصطلاح میں باپ سے مراد رب ہوتا","",{"v":200499,"fn":"(1) کتاب مقدس (مکاشفہ) 14:1-5\n(2) Life Application Study Bible, P: 2058"}],[977,"ہے جیسا کہ بائبل کی عبارت ہے:\n’’مبارک ہیں وہ جو صلح کراتے ہیں کیونکہ وہ خدا کے بیٹے کہلائیں گے۔‘‘(1)\n’’پس تم اس طرح دعا کیا کرو کہ اے ہمارے باپ تو جو آسمان پر ہے تیرا نام پاک مانا جائے۔ تیری بادشاہی آئے۔‘‘(2)\nماتھے پر اُس کا اور باپ کا نام ہونے سے مراد اللہ اور رسول کی فرمانبرداری ہے جو ان کے چہروں سے جھلک رہی ہوگی۔ اسی انداز میں ان کی صفات قرآن مجید میں بھی بیان کی گئی ہیں۔ فرمان باری تعالیٰ ہے:\n﴿سِيمَاهُمْ فِي وُجُوهِهِمْ مِنْ أَثَرِ السُّجُودِ ۚ ذٰلِكَ مَثَلُهُمْ فِي التَّوْرَاةِ﴾\n’’ان کی خصوصی پہچان ان کے چہروں پر سجدوں کا نشان ہے۔ ان کی یہ مثال تورات میں ہے۔‘‘(3)\n3 ’’ایک ایسی آواز سنائی دی جو زور کے پانی اور بڑی گرج کی سی آواز تھی جیسے بربط نواز بربط بجاتے ہوں...... گویا ایک نیا گیت گا رہے تھے:‘‘ اس سے تلبیہ اور تکبیر و تہلیل مراد ہے جسے بربط نواز کے بربط بجانے سے تشبیہ دی گئی\n[تصویر: میدان عرفات میں حجاج تلبیہ پڑھتے ہوئے]","",{"v":200500,"fn":"(1) کتاب مقدس (متی) 5:9\n(2) کتاب مقدس (متی) 6:9,10\n(3) الفتح 48:29","im":["v2_p500.jpg"]}],[978,"ہے۔ بنی اسرائیل بربط اور باجے کے ساتھ دعائیں پڑھا کرتے ہیں۔ اس پیش گوئی میں بیان کردہ لوگ بربط کے ساتھ دعائیں نہیں پڑھتے بلکہ اُن کی آوازوں کا حسن ہی ان میں بربط جیسی دلکشی پیدا کر دیتا ہے۔\nحج کے موقع پر کہے جانے والے تلبیہ کے مسنون الفاظ یہ ہیں:\n﴿لَبَّيْكَ اللَّهُمَّ لَبَّيْكَ، لَبَّيْكَ لَا شَرِيكَ لَكَ لَبَّيْكَ، إِنَّ الْحَمْدَ وَالنِّعْمَةَ لَكَ وَالْمُلْكَ، لَا شَرِيكَ لَكَ﴾\n’’میں بار بار حاضر ہوں اے اللہ! میں بار بار حاضر ہوں، میں بار بار حاضر ہوں، تیرا کوئی شریک نہیں، میں بار بار حاضر ہوں، بلاشبہ ہر طرح کی حمد و ثنا تیرے ہی لائق ہے اور سب نعمتیں تیری طرف سے ہیں اور بادشاہت تیری ہے، تیرا کوئی شریک نہیں۔‘‘(1)\n4 ’’اُن ایک لاکھ چوالیس ہزار شخصوں کے سوا جو دنیا سے خرید لیے گئے تھے کوئی اُس گیت کو نہ سیکھ سکا:‘‘ حجۃ الوداع کے موقع پر تاریخی روایات کے مطابق ایک لاکھ سے زائد افراد تھے۔ یہ سب لوگ تسبیح و تہلیل اور تلبیہ پڑھتے ہوئے فریضہ حج ادا کر رہے تھے۔\nیہ بات ہمیشہ یاد رکھنی چاہیے کہ اللہ تعالیٰ مومنوں کی جانیں جنت کے عوض خرید چکا ہے۔ یہ سودا دوامی ہے جو ہمیشہ کے لیے انجام پا چکا ہے۔ مومنوں کی جانیں خریدنے کا ذکر قرآن مجید میں یوں آیا ہے:\n﴿إِنَّ اللَّهَ اشْتَرَىٰ مِنَ الْمُؤْمِنِينَ أَنْفُسَهُمْ وَأَمْوَالَهُمْ بِأَنَّ لَهُمُ الْجَنَّةَ ۚ يُقَاتِلُونَ فِي سَبِيلِ اللَّهِ فَيَقْتُلُونَ وَيُقْتَلُونَ ۖ وَعْدًا عَلَيْهِ حَقًّا فِي التَّوْرَاةِ وَالْإِنْجِيلِ وَالْقُرْآنِ ۚ وَمَنْ أَوْفَىٰ بِعَهْدِهِ مِنَ اللَّهِ﴾\n’’بے شک اللہ نے مومنوں سے ان کی جانیں اور ان کے اموال خرید لیے ہیں، اس کے بدلے کہ یقیناً ان کے لیے جنت ہے۔ وہ اللہ کے راستے میں لڑتے ہیں۔ پس وہ قتل کرتے ہیں اور قتل کیے جاتے ہیں۔ یہ تورات، انجیل اور قرآن میں اس کے ذمے پکا وعدہ ہے اور اللہ سے زیادہ اپنا وعدہ پورا کرنے والا کون ہے؟‘‘(2)\nتحریف کے باوجود تورات میں بھی اس مضمون کی بہت سی آیات ابھی تک موجود ہیں، مثلاً:\n’’سن اے اسرائیل! خداوند ہمارا خدا ایک ہی خداوند ہے۔ تو اپنے سارے دل اور اپنی ساری جان اور اپنی ساری طاقت سے خداوند اپنے خدا سے محبت رکھ۔‘‘(3)","",{"v":200501,"fn":"(1) صحیح البخاری: 1549، صحیح مسلم: 1218\n(2) التوبة 9:111\n(3) کتاب مقدس (استثنا) 6:4,5"}],[979,"’’اور خداوند تیرا خدا تیرے اور تیری اولاد کے دل کا ختنہ کرے گا تا کہ تو خداوند اپنے خدا سے اپنے سارے دل اور اپنی ساری جان سے محبت رکھے۔‘‘(1)\nاور انجیل میں بھی ہے:\n’’اور جس کسی نے گھروں یا بھائیوں یا بہنوں یا باپ یا ماں یا بچوں یا کھیتوں کو میرے نام کی خاطر چھوڑ دیا ہے اس کو سو گنا ملے گا اور ہمیشہ کی زندگی کا وارث ہوگا۔‘‘(2)\n5 ’’یہ وہ ہیں جو عورتوں کے ساتھ آلودہ نہیں ہوئے بلکہ کنوارے ہیں:‘‘ عورتوں کے ساتھ آلودہ نہ ہونے سے مراد ان کا پاک دامن ہونا ہے۔ قرآن مجید نے بھی کامیاب مومنین کے متعلق یہی گواہی دی ہے:\n﴿وَالَّذِينَ هُمْ لِفُرُوجِهِمْ حَافِظُونَ﴾\n’’اور (کامیاب مومن) وہی ہیں جو اپنی شرم گاہوں کی حفاظت کرنے والے ہیں۔‘‘(3)\nاور اللہ تعالیٰ نے اپنے مومن بندوں کو عفت و پاکدامنی اختیار کرنے کا حکم دیتے ہوئے فرمایا ہے:\n﴿قُلْ لِلْمُؤْمِنِينَ يَغُضُّوا مِنْ أَبْصَارِهِمْ وَيَحْفَظُوا فُرُوجَهُمْ ۚ ذٰلِكَ أَزْكَىٰ لَهُمْ ۗ إِنَّ اللَّهَ خَبِيرٌ بِمَا يَصْنَعُونَ﴾\n’’مومن مردوں سے کہہ دو کہ اپنی نظریں نیچی رکھا کریں اور اپنی شرم گاہوں کی حفاظت کیا کریں۔ یہ ان کے لیے بڑی پاکیزگی کی بات ہے اور جو کام یہ کرتے ہیں، اللہ ان سے خبردار ہے۔‘‘(4)\nانجیل کی مذکورہ عبارت میں ’’کنوارے ہیں‘‘ بعد کی تحریف ہے جو پادریوں اور راہبوں کے کنوارے رہنے کے عقیدے کی تائید کے لیے کی گئی ہے اور اس کی کوئی دلیل نہیں دی گئی۔\n6 ’’یہ وہ ہیں جو برّہ کے پیچھے پیچھے چلتے ہیں، جہاں کہیں وہ جاتا ہے:‘‘ یہ صحابہ کرام رضی اللہ عنہم کی اتباع رسول صلی اللہ علیہ وسلم کی خوبی ہے جو قرآن مجید میں اس طرح بیان کی گئی ہے:\n﴿الَّذِينَ يَتَّبِعُونَ الرَّسُولَ النَّبِيَّ الْأُمِّيَّ الَّذِي يَجِدُونَهُ مَكْتُوبًا عِنْدَهُمْ فِي التَّوْرَاةِ وَالْإِنْجِيلِ﴾\n’’وہ جو اس رسول کے پیچھے پیچھے چلتے ہیں جو امی نبی ہے، جسے وہ اپنے پاس تورات اور انجیل میں لکھا ہوا پاتے ہیں۔‘‘(5)\nصحابہ کرام رضی اللہ عنہم کے اتباع رسول کے واقعات سے سیرت کی کتابیں بھری پڑی ہیں اور غیروں نے بھی اس کی","",{"v":200502,"fn":"(1) کتاب مقدس (استثنا) 30:6\n(2) کتاب مقدس (متی) 19:29\n(3) المؤمنون 23:5\n(4) النور 24:30\n(5) الأعراف 7:157"}],[980,"گواہی دی ہے۔ غزوہ تبوک کے موقع پر انھوں نے اتباع رسول کے جس جذبے کا مظاہرہ کیا، اس کی تاریخ عالم میں مثال نہیں ملتی اور اللہ تعالیٰ کی محبت کا تقاضا بھی یہی ہے کہ رسول اللہ صلی اللہ علیہ وسلم کی تعلیم کی اتباع کی جائے، ارشاد باری تعالیٰ ہے:\n﴿قُلْ إِنْ كُنْتُمْ تُحِبُّونَ اللَّهَ فَاتَّبِعُونِي يُحْبِبْكُمُ اللَّهُ وَيَغْفِرْ لَكُمْ ذُنُوبَكُمْ ۗ وَاللَّهُ غَفُورٌ رَحِيمٌ﴾\n’’آپ کہہ دیجیے: اگر تم اللہ سے محبت کرتے ہو تو میری پیروی کرو۔ اللہ تم سے محبت کرے گا اور تمھارے گناہ بخش دے گا اور اللہ بہت بخشنے والا، نہایت رحم کرنے والا ہے۔‘‘(1)\n7 ’’یہ خدا اور برّہ کے لیے پہلے پھل ہونے کے واسطے آدمیوں میں سے خرید لیے گئے ہیں:‘‘ قرآن مجید مومنین کی یہ صفت ان الفاظ میں بیان کرتا ہے:\n﴿وَالسَّابِقُونَ الْأَوَّلُونَ مِنَ الْمُهَاجِرِينَ وَالْأَنْصَارِ وَالَّذِينَ اتَّبَعُوهُمْ بِإِحْسَانٍ رَضِيَ اللَّهُ عَنْهُمْ وَرَضُوا عَنْهُ﴾\n’’اور مہاجرین اور انصار میں سے (قبول اسلام میں) سبقت کرنے والے اور وہ لوگ جنھوں نے احسان کے ساتھ ان کی پیروی کی، اللہ ان سے راضی ہو گیا اور وہ اللہ سے راضی ہو گئے۔‘‘(2)\nقرآن کریم میں ایک اور مقام پر صحابہ کرام رضی اللہ عنہم کا تذکرہ اس طرح کیا گیا ہے:\n﴿لَا تَجِدُ قَوْمًا يُؤْمِنُونَ بِاللَّهِ وَالْيَوْمِ الْآخِرِ يُوَادُّونَ مَنْ حَادَّ اللَّهَ وَرَسُولَهُ وَلَوْ كَانُوا آبَاءَهُمْ أَوْ أَبْنَاءَهُمْ أَوْ إِخْوَانَهُمْ أَوْ عَشِيرَتَهُمْ ۚ أُولٰئِكَ كَتَبَ فِي قُلُوبِهِمُ الْإِيمَانَ وَأَيَّدَهُمْ بِرُوحٍ مِنْهُ ۖ وَيُدْخِلُهُمْ جَنَّاتٍ تَجْرِي مِنْ تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا ۚ رَضِيَ اللَّهُ عَنْهُمْ وَرَضُوا عَنْهُ ۚ أُولٰئِكَ حِزْبُ اللَّهِ ۚ أَلَا إِنَّ حِزْبَ اللَّهِ هُمُ الْمُفْلِحُونَ﴾\n’’(اے نبی!) آپ (ایسی) کوئی قوم نہیں پائیں گے جو اللہ اور روز آخرت پر ایمان رکھتی ہو، کہ وہ دوستی رکھے اُن سے جو اللہ اور اس کے رسول کی مخالفت کرتے ہوں، اگرچہ وہ ان کے باپ یا ان کے بیٹے یا ان کے بھائی یا ان کا کنبہ قبیلہ ہوں۔ یہی لوگ ہیں جن کے دلوں میں اللہ نے ایمان لکھ دیا ہے اور اپنی طرف سے ایک خصوصی فیضان سے ان کی تائید کی ہے اور وہ انھیں ایسی جنتوں میں داخل کرے گا جن میں نہریں جاری ہوں گی، وہ ان میں ہمیشہ رہیں گے، اللہ ان سے راضی ہے اور وہ اس سے راضی ہیں، یہی لوگ اللہ کا گروہ ہیں، جان لو! بے شک (جو) اللہ کا گروہ ہے، وہی فلاح پانے والا ہے۔‘‘(3)","",{"v":200503,"fn":"(1) آل عمران 3:31\n(2) التوبة 9:100\n(3) المجادلة 58:22"}],[981,"سیدنا عبداللہ بن مسعود رضی اللہ عنہ نے اصحاب محمد صلی اللہ علیہ وسلم کی صفات ان الفاظ میں بیان کی ہیں:\n﴿أُولٰئِكَ أَصْحَابُ مُحَمَّدٍ صلی اللہ علیہ وسلم، كَانُوا أَفْضَلَ هٰذِهِ الْأُمَّةِ: أَبَرَّهَا قُلُوبًا، وَأَعْمَقَهَا عِلْمًا، وَأَقَلَّهَا تَكَلُّفًا، اخْتَارَهُمُ اللَّهُ لِصُحْبَةِ نَبِيِّهِ وَلِإِقَامَةِ دِينِهِ﴾\n’’اصحاب محمد (صلی اللہ علیہ وسلم) اس امت کے سب سے افضل لوگ ہیں۔ دلوں کے اعتبار سے سب سے پاکیزہ، علم میں سب سے زیادہ گہرائی والے اور سب سے کم تکلفات میں پڑنے والے ہیں۔ اللہ تعالیٰ نے انھیں اپنے نبی کی صحبت اور اقامت دین کے لیے چن لیا ہے۔‘‘(1)\nصحابہ کرام رضی اللہ عنہم کی زندگی سادگی، پاکیزگی، بے غرضی اور دنیاوی تکلفات اور تعیشات سے بے رغبتی کا بے مثال نمونہ تھی۔\n8 ’’اُن کے منہ سے کبھی جھوٹ نہ نکلا تھا۔ وہ بے عیب ہیں:‘‘ قرآن مجید میں اللہ تعالیٰ نے صحابہ کرام رضی اللہ عنہم کی سچائی کا تذکرہ کرتے ہوئے فرمایا ہے:\n﴿أُولٰئِكَ هُمُ الصَّادِقُونَ﴾\n’’یہی لوگ سچے ہیں۔‘‘(2)\nاللہ تعالیٰ نے تمام اہل ایمان کو سچے لوگوں ہی کی رفاقت اختیار کرنے کا حکم دیا ہے:\n﴿يَا أَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللَّهَ وَكُونُوا مَعَ الصَّادِقِينَ﴾\n’’اے اہل ایمان! اللہ سے ڈرتے رہو اور راست بازوں کے ساتھ رہو۔‘‘(3)\nیعنی سچ بولو اور سچ کو اختیار کرو تا کہ تم بھی اہل صدق میں سے ہو جاؤ۔ سیدنا عبداللہ بن مسعود رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n﴿عَلَيْكُمْ بِالصِّدْقِ، فَإِنَّ الصِّدْقَ يَهْدِي إِلَى الْبِرِّ، وَإِنَّ الْبِرَّ يَهْدِي إِلَى الْجَنَّةِ، وَمَا يَزَالُ الرَّجُلُ يَصْدُقُ وَيَتَحَرَّى الصِّدْقَ حَتَّىٰ يُكْتَبَ عِنْدَ اللَّهِ عَزَّ وَجَلَّ صِدِّيقًا، وَإِيَّاكُمْ وَالْكَذِبَ، فَإِنَّ الْكَذِبَ يَهْدِي إِلَى الْفُجُورِ، وَإِنَّ الْفُجُورَ يَهْدِي إِلَى النَّارِ، وَمَا يَزَالُ الرَّجُلُ يَكْذِبُ وَيَتَحَرَّى الْكَذِبَ حَتَّىٰ يُكْتَبَ عِنْدَ اللَّهِ كَذَّابًا﴾","",{"v":200504,"fn":"(1) جامع الأصول: 199/1\n(2) الحجرات 49:15، الحشر 59:8\n(3) التوبة 9:119"}]])